import type { BrutoM } from "./tipos";

export const TEXTOS: string[] = [
  "À medida que se expandia o Império Romano, a administração adaptava o esquema de construção de estradas nas novas províncias. No seu apogeu, a rede viária romana principal atingiu, consideradas as vias secundárias, cerca de 150.000 km. Os comerciantes romanos perceberam logo o interesse desses eixos viários. Distintamente de outras civilizações mediterrâneas que fundaram o seu desenvolvimento comercial quase unicamente a partir dos seus portos, os romanos utilizaram a sua rede de estradas em paralelo à sua frota comercial. Essa medida favoreceu os intercâmbios no interior do continente, provocando uma expansão mercantil fulgurante. Regiões inteiras especializaram-se e comerciaram entre si, principalmente vinho, azeite, cereais, cerâmicas e carnes.\n\nInternet: <www.wikipedia.org/wiki> (com adaptações).",
  "Leia o texto a seguir. Os números à esquerda indicam as linhas, que os itens citam como “ℓ.”.\n\n1  Houve uma época em que os homens viviam bem mais\n2  próximos do céu. E o céu, dos homens. Imagine um mundo sem\n3  luz elétrica, esparsamente povoado, um mundo praticamente\n4  sem tecnologia, fora os arados dos campos e os metais das\n5  ferramentas e das espadas. Nesse mundo, o céu tinha um\n6  significado muito diferente do que tem hoje. A sobrevivência das\n7  pessoas dependia de sua regularidade e clemência.\n8     Olhar para os céus e aprender seus ciclos era o único\n9  modo de marcar a passagem do tempo. Logo ficou claro que o\n10  céu tinha dois temperamentos: um, bem-comportado, repetitivo,\n11  como o nascer e o pôr do Sol a cada dia, as quatro fases da Lua\n12  e as quatro estações do ano; outro, imprevisível, rebelde e\n13  destruidor, o senhor das tempestades e dos furacões, dos\n14  estranhos cometas, que atravessavam lentamente os céus com\n15  sua luz fantasmagórica, e dos eclipses totais do Sol, quando dia\n16  virava noite e as estrelas e os planetas faziam-se visíveis e o Sol\n17  tingia-se de um negro profundo.\n18     Os céus eram mágicos, a morada dos deuses.\n19  O significado da vida e da morte, a previsão do futuro, o destino\n20  dos homens, tanto dos líderes quanto de seus súditos, estavam\n21  escritos nos astros. Fenômenos celestes inesperados eram\n22  profundamente temidos. Entre eles, os eclipses eram dos piores:\n23  se os deuses podiam apagar o Sol por alguns minutos,\n24  certamente poderiam fazê-lo permanentemente.\n\nMarcelo Gleiser. O céu de Ulisses. In: Folha de S.Paulo, 6/6/2008, p. 9.",
  "No tempo de andarilho\n\nProspera pouco no Pantanal o andarilho. Seis meses, durante a seca, anda. Remói caminhos e descaminhos. Abastece de perna as distâncias. E, quando as estradas somem, cobertas por águas, arrancha.\n\nO andarilho é um antipiqueteiro por vocação. Ninguém o embuçala. Não tem nome nem relógio. Vagabundear é virtude atuante para ele. Nem é um idiota programado, como nós. O próprio esmo é que o erra.\n\nChega em geral com escuro. Não salva os moradores do lugar. Menos por deseducado. Senão por alheamento e fastio.\n\nAbeira-se do galpão, mais dois cachorros, magros, pede comida, e se recolhe em sua vasilha de dormir armada no tempo.\n\nCedo, pela magrez dos cachorros que estão medindo o pátio, toda a fazenda sabe que Bernardão chegou. “Venho do oco do mundo. Vou para o oco do mundo.” É a única coisa que ele adianta. O que não adianta.\n\n(...)\n\nEnquanto as águas não descem e as estradas não se mostram, Bernardo trabalha pela bóia. Claro que resmunga. Está com raiva de quem inventou a enxada. E vai assustando o mato como um feiticeiro.\n\nOs hippies o imitam por todo o mundo. Não faz entretanto brasão de seu pioneirismo. Isso de entortar pente no cabelo intratável ele pratica de velho. A adesão pura à natureza e a inocência nasceram com ele. Sabe plantas e peixes mais que os santos.\n\nNão sei se os jovens de hoje, adeptos da natureza, conseguirão restaurar dentro deles essa inocência. Não sei se conseguirão matar dentro deles a centopéia do consumismo.\n\nPorque, já desde nada, o grande luxo de Bernardo é ser ninguém. Por fora é galalau. Por dentro não arredou de criança. É ser que não conhece ter. Tanto que inveja não se acopla nele.\n\nManoel de Barros. Livro de pré-coisas: roteiro para uma excursão poética no Pantanal. 2.ª ed. Rio de Janeiro: Record, 1997, p. 47-8.",
  "Ficou pior para quem bebe\n\nO governo ainda espera a consolidação dos dados do primeiro mês de aplicação da Lei Seca para avaliar seu impacto sobre a cassação de CNHs. As primeiras projeções indicam, porém, que as apreensões subirão, no mínimo, 10%. Antes da vigência da Lei Seca, eram suspensas ou cassadas, em média, aproximadamente 155.000 CNHs por ano. Se as previsões estiverem corretas, a média anual deve subir para próximo de 170.000. A tabela a seguir mostra esses resultados nos últimos anos (fonte: DENATRAN).\n\nano — CNHs concedidas (em milhões) — CNHs suspensas ou cassadas\n2003 — 1,8 — 148.500\n2004 — 3,4 — 314.200\n2005 — 3,2 — 115.700\n2006 — 2,2 — 98.800\n2007 — 2,8 — 112.100\n2008 — 1,5* — 64.500*\ntotal — 14,9 — 853.900\n\n* dados de janeiro a junho\n\nVeja, ed. 2.072, 6/8/2008, p. 51 (com adaptações).",
];

export const BRUTO: BrutoM[] = [
  [1, 1, "pt", "Compreensão de texto", [0], "De acordo com o texto acima, verifica-se que", ["o apogeu do Império Romano está associado à construção de estradas, em detrimento do desenvolvimento das vias portuárias.", "as conquistas territoriais do Império Romano foram acompanhadas de condições favorecedoras de atividades comerciais.", "a conquista política de territórios pelo Império Romano era fruto do patrocínio dos comerciantes.", "todas as civilizações mediterrâneas, excetuando-se a romana, privilegiavam o comércio marítimo.", "o principal interesse da administração romana era o comércio no continente, com regiões cuja produção era especializada."], "B", "O texto liga a expansão do Império à construção de estradas, que favoreceram o comércio no interior do continente: as conquistas vieram acompanhadas de condições boas para o comércio. A erra no “em detrimento” (as estradas funcionavam em paralelo à frota), C e E inventam causas que o texto não dá, e D generaliza (“todas”) o que o texto diz de “outras civilizações”.", ""],
  [2, 1, "pt", "Correção gramatical", [], "Considerando que os fragmentos de texto incluídos nas opções abaixo, na ordem em que são apresentados, são partes sucessivas de um texto adaptado (Internet: <www.wikipedia.org/wiki>), assinale a opção em que foram atendidas as normas da língua padrão escrita.", ["À proporção em que o Império Romano conquistou territórios, as novas províncias seriam contempladas com estradas, as quais eram construídas com base em esquema já adotado em outras localidades.", "No auge da dominação dos romanos, na região mediterrânea o principal complexo viário do Império, media, inclusive com as estradas marginais, aproximadamente 150.000 quilômetros.", "Os comerciantes romanos vislumbram a vantagem dessa obra para o desenvolvimento comercial e diferente de outros povos do Mediterrâneo, utilizaram as estradas para aumentarem o lucro de sua atividade.", "Esse fato incrementou as transações comerciais no interior continental, o que acarretou vigorosa expansão mercantil do Império Romano e comércio especializado em determinados produtos.", "O comércio dos romanos, que, no passado, fora realizado, unicamente por meio de portos, passaram a dedicar-se principalmente, a venda de produtos alimentícios, dentre os quais destacam-se vinho, azeite, cereais, carnes, entre outros."], "D", "Só a D está de acordo com a norma. A mistura tempos (“conquistou… seriam contempladas”). B separa o sujeito do verbo com vírgula (“complexo viário do Império, media”). C usa o presente “vislumbram” num relato no passado e deixa sem a vírgula de abertura o trecho intercalado. E erra a concordância (“O comércio… passaram”), a crase (“a venda” pede “à venda”) e põe vírgulas indevidas.", ""],
  [3, 1, "pt", "Correção gramatical", [], "Assinale a opção em que o trecho apresentado atende plenamente às normas gramaticais.\n\n(Opções adaptadas de Internet: <www.wikipedia.org/wiki>.)", ["Até 400 a.C., os romanos utilizavam caminhos de terra para deslocar-se da sua capital as cidades vizinhas. O ataque gaulês de Breno, em 390 a.C., que se revelou desastroso para os romanos, mostrou a ineficácia do sistema defensivo de Roma, devido principalmente a lentidão de movimentação das tropas sobre o que eram apenas caminhos pouco aptos para eles se moverem.", "A necessidade de melhor defesa, associada à vontade de expansão e de hegemonia sobre a Itália, levou a República Romana, ainda frágil e ameaçada, a pôr em questão estruturas escassamente adaptadas a esses desejos. Eram necessárias rotas sólidas que permitissem a circulação mais rápida e segura, mas, sobretudo, que facilitassem a mobilidade das tropas.", "A primeira via em território do Império Romano foi criada em 312 a.C. por Ápio Cláudio Cego, para unir Roma à cidade de Cápua e fora denominada Via Ápia. Em finais da República, o conjunto do território da península italiana estava dotada com grandes arterias, ostentando cada rota o nome do censor que a criara. Essas vias não estavam pavimentadas, salvo no interior das cidades.", "Os romanos destacaram-se como engenheiros. Suas obras estenderam-se por todo Império, e grande parte da divulgação se deveu a extensa rede viária. Apesar de não oferecer o conforto do asfalto dos dias de hoje, dado que as rochas de basalto não proporcionam grande continuidade e suavidade ao terreno, a verdade é que, essas rochas encontram-se 2.000 anos depois, ainda bem fixadas nos percursos.", "O fato de as rochas das vias romanas estarem fixas até hoje deve-se, provavelmente, a técnica de preparação do terreno, no qual eram colocadas várias camadas de materiais para assegurar a sua estabilidade e, só no final, era feito, com as rochas, a cobertura. Essas vias são, atualmente, protegidas como patrimônio mundial. A grande extensão da cobertura oferecida pelas estradas romanas deu origem ao ditado popular “todos os caminhos levam à Roma”."], "B", "Só a B atende à norma. A: faltam crases (“às cidades vizinhas”, “à lentidão”) e “eles” deveria ser “elas” (as tropas). C: “fora denominada” deveria ser “foi”, “dotada” deveria concordar com “conjunto” e falta o acento de “artérias”. D: “à extensa rede” pede crase, “todo o Império” pede artigo e há vírgula indevida depois de “é que”. E: “à técnica” pede crase, “era feita a cobertura” pede o feminino e “a Roma” não leva crase.", ""],
  [4, 1, "pt", "Redação oficial", [], "Considerando as prescrições relativas às comunicações oficiais, assinale a opção correta.", ["Os três tipos de expedientes que seguem o padrão ofício — exposição de motivos, aviso e ofício — têm a mesma finalidade e se diferenciam apenas por sua extensão e pelo detalhamento das informações neles contidas.", "Diferentemente da ata, a exposição de motivos deve, obrigatoriamente, conter, no máximo, duas idéias por parágrafo.", "Caso haja grande distanciamento hierárquico entre o signatário e o destinatário de uma comunicação oficial, recomenda-se o emprego do fecho “Mui respeitosamente”.", "Em todas as comunicações oficiais, os pronomes possessivos que se refiram a pronomes de tratamento são sempre os da terceira pessoa. Por exemplo, o segmento correto é “Vossa Senhoria nomeará seu substituto”, e não, “Vossa Senhoria nomeará vosso substituto”.", "Com o intuito de uniformização do emprego de pronomes de tratamento nos vocativos das comunicações oficiais, foi estabelecido como regra o emprego dos pronomes de tratamento Excelentíssimo Senhor e Excelentíssima Senhora, excetuando-se os casos em que tal comunicação se dirija ao papa ou ao reitor de uma universidade."], "D", "Com os pronomes de tratamento, verbo e possessivo vão para a 3ª pessoa: “Vossa Senhoria nomeará seu substituto”. A erra porque os expedientes do padrão ofício se distinguem pela finalidade e pelo destinatário; B inventa uma regra; C usa um fecho que o Manual não prevê (só “Respeitosamente” e “Atenciosamente”); E erra porque “Excelentíssimo Senhor” no vocativo era reservado aos chefes de Poder.", "Na data da prova valia a 2ª edição do Manual de Redação da Presidência da República (2002). A 3ª edição (2018) acabou com a diferença entre ofício, aviso e memorando: hoje todos seguem o padrão ofício e se chamam ofício. Depois, o Decreto 9.758/2019 passou a usar só “senhor” (e não “Vossa Senhoria”) com agentes públicos federais; a regra do possessivo de 3ª pessoa continua."],
  [6, 1, "pt", "Coesão e referência", [1], "Assinale a opção correta a respeito de elementos de coesão do texto.", ["No período “E o céu, dos homens” (ℓ.2), a vírgula foi empregada para indicar a oposição dos termos “céu” e “homens”.", "O emprego de Naquele mundo, em vez de “Nesse mundo” (ℓ.5), seria mais adequado, visto que o pronome se refere a um mundo muito remoto.", "Na linha 7, a referência do pronome “sua” é o termo “pessoas”.", "Nas linhas 10 e 12, o emprego das expressões o primeiro e o segundo no lugar, respectivamente, de “um” e “outro” tornaria o texto mais claro.", "A expressão “fazê-lo” (ℓ.24), que, no texto, tem o sentido de apagar o Sol, é recurso coesivo utilizado para se evitar a repetição de uma oração."], "E", "“Fazê-lo” retoma “apagar o Sol” e evita repetir a oração. A vírgula de “E o céu, dos homens” marca a elipse do verbo (o céu vivia próximo dos homens), não oposição (A). “Nesse” retoma o mundo já descrito e está bem empregado (B). “Sua” se refere ao céu, não às pessoas (C). Trocar “um” e “outro” não deixaria o trecho mais claro (D).", ""],
  [7, 1, "pt", "Resumo", [1], "Assinale a opção em que é apresentado resumo do primeiro parágrafo do texto de acordo com a técnica de resumo de frases e textos.", ["Em um mundo sem energia elétrica e quase sem tecnologia, os homens atribuíam ao céu o poder de lhes determinar a sobrevivência, o que os tornava mais próximos do céu do que são atualmente.", "Nos primórdios da humanidade, quando os homens usavam apenas arados, espadas e algumas ferramentas, os homens sabiam que, diferentemente do que ocorre hoje, dependiam da clemência do céu e da regularidade das tempestades.", "Há muitos e muitos anos, quando ainda não estava disponível a energia elétrica e quando a tecnologia era muito atrasada e pouco útil, os homens valorizavam muito o que observavam de regularidade no céu porque era ele que lhes indicava se a sobrevivência deles corria risco.", "Os homens já viveram mais próximos do céu do que vivem nos dias atuais. Isso aconteceu porque não se usava luz elétrica nem havia toda a tecnologia atual. Naquela época, os homens respeitavam o céu, porque não sabiam defender-se de tempestades.", "Num passado remoto, as únicas tecnologias que os homens dominavam eram o arado e metais de ferramentas e espadas. Não havia luz elétrica nessa época e, por isso, o céu era observado apenas à noite, quando os homens temiam os fenômenos inesperados. Isso os aproximava e garantiu a sobrevivência da espécie humana."], "A", "O resumo deve manter só as ideias centrais, sem acrescentar nada. A faz isso: sem eletricidade e quase sem tecnologia, a sobrevivência dependia do céu, por isso os homens eram mais próximos dele. B troca a regularidade do céu pela “regularidade das tempestades”; C acrescenta juízo (“pouco útil”); D e E inventam causas e fatos que o parágrafo não traz.", ""],
  [8, 1, "pt", "Clareza e correção", [1], "Considerando que os fragmentos de texto incluídos nas opções abaixo, na ordem em que são apresentados, são partes sucessivas de um texto adaptado de Marcelo Gleiser, assinale a opção em que, no fragmento adaptado, foram atendidos plenamente os preceitos de clareza e correção gramatical.", ["Em maio de 2008, dois astrônomos publicaram um estudo que argumentava que a Odisséia, famoso poema de Homero, faz referência a um eclipse que ocorreu de fato no mar Egeu dia 16 de abril de 1178 a.C. A idéia não é nova, tendo sido proposta há cem anos atrás por astrônomos interessados em datar o saque de Tróia e o retorno do herói Odisseu (Ulisses, para os romanos) para a sua adorada (e extremamente paciente) Penélope, que esperou por ela por dez anos.", "A novidade do novo trabalho é a confluência de outros eventos astronômicos, já anteriormente mencionados e ocorridos, que apoiam a tese de que Homero tinha o eclipse, em mente, quando escreveu as famosas linhas: “O Sol sumiu do céu e uma escuridão funesta cobriu tudo!”", "Vasculhando o texto de Homero famoso, os astrônomos encontraram referências a lua nova, condição básica para um eclipse total, as estrelas usadas por Odisseu para orientar-lhe no retorno à casa e à aparição de Vênus logo após a chegada em Ítaca.", "O mais fascinante da descoberta é que Homero supostamente escreveu a Odisséia no final do século 8.º a.C., mais de 400 anos após o evento, onde não existia quaisquer relatos de eclipses datando do século 8.º a.C. (se existiram, foram perdidos). O fato de Homero ter mencionado o eclipse mostra que o imenso efeito que provocava o fenômeno, cujo o terror que despertou ficou gravado na memória coletiva e passado oralmente às gerações futuras até chegar nos ouvidos do poeta.", "A descoberta dos astrônomos confirma a idéia de complementaridade entre ciência e arte, visto que o poeta, em seu texto, referiu-se alegoricamente a um fenômeno celeste para tornar mágico um momento extremamente dramático da trama narrativa, e a descrição da regularidade do céu nas leis de gravitação de Newton permite que o passado celeste seja conhecido em detalhes."], "E", "Só a E está clara e correta. A tem redundância (“há cem anos atrás”) e “esperou por ela” deveria ser “por ele”. B tem redundâncias (“novidade do novo”, “já anteriormente”) e vírgulas indevidas. C tem ordem confusa (“texto de Homero famoso”), falta a crase de “à lua nova” e “orientar-lhe” deveria ser “orientá-lo”. D usa “onde” para tempo, erra a concordância (“não existia quaisquer relatos”), escreve “cujo o” e “chegar nos ouvidos”.", ""],
  [9, 1, "pt", "Compreensão de texto", [2], "De acordo com o texto, o andarilho", ["percebe que as pessoas dos lugares aonde chega têm expectativa do aparecimento de um salvador, mas ele mantém-se alheio às crenças locais.", "dispensa qualquer tipo de relação com os habitantes dos lugares por onde passa porque não é “um idiota programado”.", "não cumprimenta os moradores do lugar onde “arrancha” porque se mantém alheio e considera enfadonho o ato social do cumprimento.", "é um cidadão típico que inspira todos os jovens que já nasceram valorizando a natureza e cultuando a inocência.", "manifesta atitudes infantis que contrastam com sua aparência robusta porque sua meta é ser ninguém em um mundo que só conhece o ter."], "C", "“Não salva os moradores” quer dizer que ele não os cumprimenta (salvar = saudar), “menos por deseducado, senão por alheamento e fastio”. A lê “salvar” como “ser salvador”. B exagera: ele pede comida e trabalha pela boia. D e E contrariam o texto: ele não é um cidadão típico, e “não arredou de criança” fala de inocência, não de atitudes infantis.", ""],
  [10, 1, "pt", "Funções da linguagem", [2], "Utilizando a função poética da linguagem, o autor do texto", ["faz apologia do modo de vida do andarilho e, conseqüentemente, de todos aqueles que desprezam o trabalho.", "critica os valores de indivíduos que compõem a sociedade atual ao contrapor-lhes a beleza que percebe na figura do andarilho.", "apresenta a figura idealizada do andarilho, buscando convencer o leitor a se solidarizar com pessoas à margem da sociedade e a lhes oferecer emprego.", "descreve um andarilho cujo objetivo “é ser ninguém”, para ressaltar a influência desse tipo social no movimento tanto de jovens que romperam com os valores sociais estabelecidos quanto dos jovens consumistas.", "desaprova o modo de vida do andarilho, como comprova o trecho “Vagabundear é virtude atuante para ele”."], "B", "O autor exalta o andarilho e o põe contra “um idiota programado, como nós” e contra “a centopeia do consumismo”: é uma crítica aos valores da sociedade atual. Ele não faz apologia de quem despreza o trabalho (A), não quer convencer ninguém a dar emprego (C), não fala de influência sobre jovens consumistas (D) e não desaprova o andarilho: chama de virtude o seu vagabundear (E).", ""],
  [11, 1, "rlm", "Lógica de proposições", [], "Em um posto de fiscalização da PRF, cinco veículos foram abordados por estarem com alguns caracteres das placas de identificação cobertos por uma tinta que não permitia o reconhecimento, como ilustradas abaixo, em que as interrogações indicam os caracteres ilegíveis.\n\nI: AEU-237?\nII: KJI-??22\nIII: ??A-1???\nIV: ???-???8\nV: UA?-1?89\n\nOs policiais que fizeram a abordagem receberam a seguinte informação: se todas as três letras forem vogais, então o número, formado por quatro algarismos, é par. Para verificar se essa informação está correta, os policiais deverão retirar a tinta das placas", ["I, II e V.", "I, III e IV.", "I, III e V.", "II, III e IV.", "II, IV e V."], "C", "A regra “se as três letras forem vogais, então o número é par” só é desmentida por uma placa com três vogais e número ímpar. Não precisam ser vistas a II (K e J são consoantes) nem a IV (termina em 8, número par). Precisam ser vistas a I (três vogais, último algarismo ilegível), a III (letras e número ilegíveis) e a V (número ímpar, terceira letra ilegível).", ""],
  [12, 1, "rlm", "Lógica de argumentação", [], "Em um posto de fiscalização da PRF, os veículos A, B e C foram abordados, e os seus condutores, Pedro, Jorge e Mário, foram autuados pelas seguintes infrações: (i) um deles estava dirigindo alcoolizado; (ii) outro apresentou a CNH vencida; (iii) a CNH apresentada pelo terceiro motorista era de categoria inferior à exigida para conduzir o veículo que ele dirigia. Sabe-se que Pedro era o condutor do veículo C; o motorista que apresentou a CNH vencida conduzia o veículo B; Mário era quem estava dirigindo alcoolizado. Com relação a essa situação hipotética, julgue os itens que se seguem.\n\nI A CNH do motorista do veículo A era de categoria inferior à exigida.\n\nII Mário não era o condutor do veículo A.\n\nIII Jorge era o condutor do veículo B.\n\nIV A CNH de Pedro estava vencida.\n\nV A proposição “Se Pedro apresentou CNH vencida, então Mário é o condutor do veículo B” é verdadeira.\n\nEstão certos apenas os itens", ["I e II.", "I e IV.", "II e III.", "III e V.", "IV e V."], "D", "Pedro dirigia C. A CNH vencida era do motorista de B, e Mário estava alcoolizado, logo não dirigia B: Mário dirigia A e Jorge dirigia B, com a CNH vencida. Sobra para Pedro a CNH de categoria inferior. I, II e IV são falsos. III é verdadeiro, e V também: a condicional tem antecedente falso (Pedro não apresentou CNH vencida), por isso é verdadeira.", ""],
  [13, 1, "rlm", "Média", [3], "Para que a média de CNHs suspensas ou cassadas, de 2003 a 2008, atinja o valor previsto de 170.000, será necessário que, em 2008, a quantidade de CNHs suspensas ou cassadas seja um número", ["inferior a 180.000.", "superior a 180.000 e inferior a 200.000.", "superior a 200.000 e inferior a 220.000.", "superior a 220.000 e inferior a 240.000.", "superior a 240.000."], "D", "Média de 170.000 em 6 anos dá um total de 1.020.000. De 2003 a 2007 foram 789.300. Em 2008 seriam necessárias 1.020.000 − 789.300 = 230.700, entre 220.000 e 240.000.", ""],
  [14, 1, "rlm", "Razão e proporção", [3], "Suponha que, em 2006, nenhuma CNH tenha sofrido simultaneamente as penalidades de suspensão e de cassação e que, nesse mesmo ano, para cada 5 CNHs suspensas, 3 eram cassadas. Nessa situação, é correto afirmar que a diferença entre o número de CNHs suspensas e o número de CNHs cassadas é", ["inferior a 24.000.", "superior a 24.000 e inferior a 25.000.", "superior a 25.000 e inferior a 26.000.", "superior a 26.000 e inferior a 27.000.", "superior a 27.000."], "B", "Em 2006 foram 98.800 CNHs. Na razão de 5 suspensas para 3 cassadas, são 8 partes de 12.350. A diferença é de 2 partes: 24.700.", ""],
  [15, 1, "rlm", "Progressão aritmética", [3], "Supondo que, neste ano de 2008, a variação na quantidade de CNHs emitidas de um mês para o mês anterior seja mantida constante e que, em fevereiro de 2008, tenham sido emitidas 175.000 habilitações, então o total de habilitações emitidas em 2008 será, em milhões,", ["inferior a 3.", "superior a 3 e inferior a 3,5.", "superior a 3,5 e inferior a 4.", "superior a 4 e inferior a 4,5.", "superior a 4,5."], "E", "De janeiro a junho foram 1,5 milhão, e a variação mensal é constante (PA). Com a₂ = 175.000 e S₆ = 1.500.000: a₁ + a₆ = 500.000, logo 2a₁ + 5r = 500.000 e a₁ + r = 175.000. Daí r = 50.000 e a₁ = 125.000. No ano: S₁₂ = 6 × (2 × 125.000 + 11 × 50.000) = 4.800.000, ou seja, 4,8 milhões.", ""],
  [16, 1, "rlm", "Porcentagem", [3], "Considerando que, em 2005, o motivo de todas as cassações ou suspensões de CNH tenha sido dirigir veículo automotor depois de ingerir bebida alcoólica em quantidade superior à permitida, e que uma pesquisa tenha revelado que 12% da população brasileira admitia dirigir veículo automotor depois de ingerir bebida alcoólica em quantidade superior à permitida, e considerando, também, que a quantidade de CNHs cassadas ou suspensas corresponda, proporcionalmente, a 3 em cada 600 indivíduos que admitiam dirigir veículo automotor depois de ingerir bebida alcoólica em quantidade superior à permitida, é correto inferir que, em 2005, a população brasileira era, em milhões,", ["inferior a 180.", "superior a 180 e inferior a 185.", "superior a 185 e inferior a 190.", "superior a 190 e inferior a 195.", "superior a 195."], "D", "Em 2005 foram 115.700 CNHs suspensas ou cassadas, 3 em cada 600 (1 em 200) dos que admitiam dirigir depois de beber. Esses eram 115.700 × 200 = 23.140.000, ou 12% da população. A população era 23.140.000 ÷ 0,12 ≈ 192,8 milhões.", ""],
  [19, 1, "rlm", "Equação do 2º grau", [], "No ano de 2006, um indivíduo pagou R$ 4.000,00 pelas multas de trânsito recebidas, por ter cometido várias vezes um mesmo tipo de infração de trânsito, e o valor de cada uma dessas multas foi superior a R$ 200,00. Em 2007, o valor da multa pela mesma infração sofreu um reajuste de R$ 40,00, e esse mesmo indivíduo recebeu 3 multas a mais que em 2006, pagando um total de R$ 6.720,00. Nessa situação, em 2006, o valor de cada multa era", ["inferior a R$ 750,00.", "superior R$ 750,00 e inferior a R$ 850,00.", "superior a R$ 850,00 e inferior a R$ 950,00.", "superior a R$ 950,00 e inferior a R$ 1.050,00.", "superior a R$ 1.050,00."], "B", "Com n multas de valor x em 2006: n·x = 4.000. Em 2007: (n + 3)(x + 40) = 6.720, o que dá 40n + 3x = 2.600. Trocando n por 4.000/x: 3x² − 2.600x + 160.000 = 0, com raízes 800 e cerca de 66,7. Como x > 200, cada multa valia R$ 800,00.", ""],
  [20, 1, "rlm", "Geometria espacial", [], "Considere que um cilindro circular reto seja inscrito em um cone circular reto de raio da base igual a 10 cm e altura igual a 25 cm, de forma que a base do cilindro esteja no mesmo plano da base do cone. Em face dessas informações e, considerando, ainda, que h e r correspondam à altura e ao raio da base do cilindro, respectivamente, assinale a opção correta.", ["A função afim que descreve h como função de r é crescente.", "O volume do cilindro como uma função de r é uma função quadrática.", "Se A(r) é a área lateral do cilindro em função de r, então A(r) = 50πr(1 − r/10).", "É possível encontrar um cilindro de raio da base igual a 2 cm e altura igual a 19 cm que esteja inscrito no referido cone.", "O cilindro de maior área lateral que pode ser inscrito no referido cone tem raio da base superior a 6 cm."], "C", "Por semelhança, h/25 = (10 − r)/10, logo h = 25 − 2,5r: função afim decrescente (A errada). O volume πr²(25 − 2,5r) é do 3º grau (B errada). A área lateral é 2πrh = 50πr(1 − r/10) (C certa). Com r = 2, o cilindro inscrito tem h = 20, não 19 (D errada). A área lateral 50πr − 5πr² é máxima em r = 5, não acima de 6 (E errada).", ""],
  [21, 1, "atualidades", "Centro-Oeste", [], "O povoamento do Centro-Oeste resulta, desde o período colonial, de movimentos migratórios. No século XX, a construção da nova capital brasileira atraiu novas levas de imigrantes, em especial do Nordeste, secundado pelo Sul e pelo Sudeste. Nos últimos tempos, o Norte e o Nordeste respondem pelo maior número de imigrantes que chegam à região. Segundo o censo de 2000, de cada três nortistas que emigram, um se dirige para o Centro-Oeste. Com o auxílio dessas informações e considerando o processo histórico de povoamento do Centro-Oeste brasileiro, assinale a opção correta.", ["A grande extensão territorial do Centro-Oeste deriva do fato de a colonização do Brasil ter-se iniciado nessa região, conquistada aos espanhóis, que dela se apossaram em conseqüência do Tratado de Tordesilhas.", "Sucessivas correntes migratórias, do século XVII ao presente, fizeram do Centro-Oeste a região brasileira mais populosa proporcionalmente à extensão de sua área geográfica.", "Bonito, em Mato Grosso, e o Pantanal Mato-Grossense, cortado pelo rio Araguaia, são dois dos mais expressivos exemplos de belezas naturais com que conta o Centro-Oeste para o desenvolvimento do ecoturismo.", "Incentivos oferecidos pelo regime militar, na década de 70, explicam o fato de que, mais recentemente, brasileiros provenientes do Sul e do Sudeste sejam os imigrantes que mais se dirigem ao Centro-Oeste.", "Meta-síntese do programa de governo de JK, Brasília, além das inovações de seu projeto urbanístico e arquitetônico, contribuiu para a interiorização do desenvolvimento brasileiro e tornou-se pólo de atração de imigrantes."], "E", "Brasília, meta-síntese do Plano de Metas de JK, levou o desenvolvimento para o interior e virou polo de atração de migrantes. A erra: a colonização começou pelo litoral, não pelo Centro-Oeste. B erra: a região tem baixa densidade demográfica. C erra duas vezes: Bonito fica em Mato Grosso do Sul, e o Pantanal é cortado pelo rio Paraguai, não pelo Araguaia. D contraria o texto, que aponta o Norte e o Nordeste como origem da maior parte dos migrantes recentes.", ""],
  [22, 1, "atualidades", "Centro-Oeste", [], "Nos anos 70 do século passado, cerca de 60% da população do Centro-Oeste vivia no campo. Em 2006, aproximadamente 74% estavam nas cidades. A crescente mecanização da agricultura, que libera mão-de-obra, e os fluxos migratórios vindos de outras regiões brasileiras são fatores relevantes para o vigoroso processo de urbanização observado nessa região. A propósito dessa realidade, assinale a opção correta.", ["O êxodo rural, que amplia consideravelmente a população urbana, é também reflexo da mecanização das atividades rurais desenvolvidas no Centro-Oeste, as quais têm no denominado agronegócio, na atualidade, um de seus símbolos mais expressivos.", "O significativo crescimento da população urbana no Centro-Oeste fez dessa região autêntica exceção no conjunto do país, ainda fortemente marcado pela força econômica e política do campo, o que explica a lenta expansão dos centros urbanos brasileiros.", "Apesar da existência de um Plano Piloto, com a maior renda per capita do país, o DF, com seus dois milhões de habitantes, empurra para baixo os indicadores sociais e econômicos do Centro-Oeste, a começar pela taxa de escolaridade da população.", "Ao contrário da atual tendência de interiorização das atividades econômicas no país, o desenvolvimento no Centro-Oeste concentra-se em torno das capitais, a começar pelo agronegócio.", "A ausência da escravidão no Centro-Oeste, no período colonial, e a implacável perseguição histórica aos índios explicam a inexistência de afro-descendentes e de indígenas na composição demográfica dessa região."], "A", "A mecanização do campo libera mão de obra e alimenta o êxodo rural; o agronegócio é hoje o símbolo dessa agricultura mecanizada. B erra: o Brasil inteiro é fortemente urbanizado, o Centro-Oeste não é exceção. C erra: o DF puxa para cima, não para baixo, os indicadores da região. D erra: o agronegócio se espalha pelo interior, longe das capitais. E erra: houve escravidão na região (mineração em Goiás e Mato Grosso), e afrodescendentes e indígenas fazem parte da sua população.", ""],
  [23, 1, "atualidades", "Amazônia e energia", [], "A celeuma em torno de duas hidrelétricas a serem construídas em Rondônia envolveu desde preocupações ambientais até o modelo das linhas de transmissão de energia a ser utilizado, passando por disputa empresarial entre grupos interessados nas obras. Essas usinas, de Jirau e Santo Antônio, irão integrar o complexo hidrelétrico do rio", ["Branco.", "Solimões.", "Madeira.", "Negro.", "Tocantins."], "C", "Jirau e Santo Antônio ficam no rio Madeira, perto de Porto Velho (RO). Os outros rios não passam por esse trecho de Rondônia.", ""],
  [24, 1, "atualidades", "Amazônia e meio ambiente", [], "O governo brasileiro anunciou sua intenção de, em 2009, licitar e conceder a exploração de 4 milhões de florestas públicas situadas, principalmente, em Rondônia, Amazonas, Amapá, Pará e Acre. Ao afirmar que o modelo de gestão de florestas públicas viabiliza a conservação das áreas licitadas e torna economicamente viável, socialmente justa e ambientalmente adequada a exploração, o poder público pretende aproximar-se de um modelo de desenvolvimento entendido atualmente como", ["integrado à economia de mercado globalizada, que enfatiza os resultados econômicos.", "monitorado por ONGs e submetido às leis do mercado.", "refratário à ingerência externa e às teses ambientalistas mais difundidas no mundo.", "sustentável, em que a geração de riquezas está associada à preservação da vida no presente e no futuro.", "pragmático, segundo o qual a necessidade e a viabilidade do progresso devem ser defendidas a qualquer custo."], "D", "Gerar riqueza com a floresta em pé, de modo economicamente viável, socialmente justo e ambientalmente adequado, sem comprometer as gerações futuras, é a definição de desenvolvimento sustentável. As outras opções põem o mercado ou o progresso “a qualquer custo” acima da conservação, ou rejeitam as teses ambientais, o contrário do que o texto descreve. O enunciado foi mantido como aplicado (“4 milhões de florestas públicas”).", ""],
  [25, 1, "atualidades", "Integração sul-americana", [], "Projeto avaliado em 800 milhões de dólares, iniciado em 2005 e com previsão de término para 2010, a Interoceânica dinamizará a integração entre vizinhos, ao partir de Assis Brasil, no Acre, para desaguar nos portos peruanos de San Juan e Ilo. A construção da estrada gera enorme expectativa para negócios entre os países. Serão mais de 2,5 mil quilômetros, dos quais 60% já estão construídos em diferentes blocos, que ainda precisam ser conectados.\n\nJornal do Brasil, 27/7/2008, p. E4 (com adaptações).\n\nTendo o texto acima como referência inicial e considerando o objetivo da obra nele mencionada, assinale a opção incorreta.", ["Com a construção da estrada, pretende-se facilitar o trânsito de mercadorias brasileiras em direção aos cada vez mais promissores mercados da costa do oceano Pacífico.", "A obra, já em andamento, com pouco mais da metade da construção concluída, impulsionará diretamente as relações Norte-Sul no cenário globalizado da economia mundial.", "As atuais alternativas de exportação, como os portos de Paranaguá e de Santos, representam custos muito elevados para produtos da região Norte.", "Uma rodovia como a Interoceânica facilitará a aproximação dos interesses comerciais brasileiros com o rico mercado da costa oeste norte-americana.", "Em síntese, a estrada a que se refere o texto possibilitará a ligação, por terra, entre os oceanos Atlântico e Pacífico, cortando a América do Sul."], "B", "A questão pede a incorreta. A Interoceânica liga o Brasil ao Peru e aos portos do Pacífico: é integração entre vizinhos da América do Sul (relação Sul-Sul), não “relação Norte-Sul”. As demais estão de acordo com o objetivo da obra: escoar produtos para o Pacífico, fugir dos custos de portos distantes do Atlântico, chegar aos mercados da Ásia e da costa oeste da América e ligar os dois oceanos por terra.", ""],
  [26, 1, "atualidades", "Amazônia e agronegócio", [], "O cultivo de grãos na Amazônia — entre eles a soja, apontada como uma das vilãs do desmatamento — pode ser uma alternativa para a recuperação de áreas já degradadas da floresta. Uma tecnologia desenvolvida pela EMBRAPA, que consiste na integração de culturas como o cultivo de grãos, a pecuária e o reflorestamento, começa a ser implantada em fazendas experimentais na região Norte do país. É o chamado sistema integrado de produção.\n\nFolha de S.Paulo, 3/2/2008, p. A18 (com adaptações).\n\nTendo o texto acima como referência inicial e considerando as implicações do tema por ele focalizado, assinale a opção incorreta.", ["O comércio de grãos, no atual estágio da economia mundial globalizada, adquire importância capital devido ao montante de recursos que movimenta.", "O Brasil tem no agronegócio, que faz da soja uma de suas estrelas, um de seus mais fortes instrumentos para inserção no mercado mundial.", "A empresa estatal mencionada no texto torna o Brasil uma referência internacional no campo da pesquisa científica vinculada ao campo.", "Áreas já degradadas da floresta, conforme se afirma no texto, podem ser as utilizadas pela pecuária, mas abandonadas pela exaustão do solo usado pelo gado.", "Infere-se do texto que os lucros da ampliação de áreas de plantio na Amazônia compensam os efeitos ambientais do desmatamento na região."], "E", "A questão pede a incorreta. O texto propõe usar áreas já degradadas justamente para não desmatar mais; não diz que os lucros compensam o desmatamento. As demais são corretas: o comércio de grãos movimenta muito dinheiro, a soja é estrela do agronegócio exportador, a EMBRAPA é referência em pesquisa agropecuária e pastagens abandonadas estão entre as áreas degradadas.", ""],
  [27, 1, "atualidades", "Amazônia e mineração", [], "Em geral, a região Norte do Brasil tem sua economia baseada no extrativismo vegetal, a exemplo do látex, do açaí, da madeira e da castanha. Não obstante, a região é muito rica em minérios. Exemplos disso são a serra do Navio, no Amapá, rica em manganês, e a serra dos Carajás, no Pará, de onde se extrai", ["a maior parte da produção aurífera brasileira.", "a maior concentração de diamantes do país.", "a totalidade da bauxita existente na América do Sul.", "grande parte do minério de ferro que o Brasil exporta.", "o combustível que impulsiona as usinas de Angra dos Reis."], "D", "Carajás (PA) tem uma das maiores reservas de minério de ferro do mundo, e dali sai grande parte do ferro que o Brasil exporta. O ouro e o diamante não se concentram ali, a bauxita não é exclusividade da região e Angra dos Reis usa urânio, não minério de Carajás.", ""],
  [28, 1, "atualidades", "Amazônia e soberania", [], "Portaria publicada no Diário Oficial da União — que obriga todas as entidades autorizadas a trabalhar em áreas indígenas e de proteção ao meio ambiente a se recadastrarem em um prazo de 120 dias — permitirá a expulsão do país das ONGs em situação irregular. Oficialmente, o governo não revela, mas já tem uma lista com cerca de 20 ONGs estrangeiras sob ameaça de expulsão. Principalmente aquelas ligadas a grupos externos que pregam a internacionalização da Amazônia.\n\nJornal do Brasil, 5/7/2008, capa (com adaptações).\n\nTendo o texto acima como referência inicial e considerando os múltiplos aspectos do tema que ele aborda, assinale a opção correta.", ["Temeroso diante de eventual reação da comunidade internacional, o Estado brasileiro silencia-se diante da presença de organismos e instituições estrangeiras com atuação no território nacional.", "As ONGs expandiram-se no mundo contemporâneo, especialmente na primeira metade do século XX, tendo por foco principal a luta pelo desarmamento e pelo fim dos conflitos regionais.", "No Congresso Nacional, parlamentares de diferentes correntes partidárias, sobretudo da região Norte, têm-se manifestado criticamente quanto à ação de ONGs que atuam junto a comunidades indígenas.", "A tese de internacionalização da Amazônia, mencionada no texto, é inédita, tendo surgido no início do século XXI em alguns dos principais centros dirigentes da economia mundial.", "Infere-se do texto que a exigência de recadastramento das ONGs é mera formalidade, já que não se tem notícia, até o momento, de indícios de irregularidade no funcionamento dessas organizações."], "C", "Parlamentares de vários partidos, em especial do Norte, criticavam a atuação de ONGs junto a comunidades indígenas. A erra: a própria portaria mostra que o Estado agiu. B erra: as ONGs se multiplicaram sobretudo na segunda metade do século XX, com focos variados. D erra: a ideia de internacionalizar a Amazônia é antiga. E contraria o texto, que fala em lista de ONGs ameaçadas de expulsão.", ""],
  [29, 1, "atualidades", "Zona Franca de Manaus", [], "Surgida em 1969, a Superintendência da Zona Franca de Manaus (SUFRAMA) impulsionou a economia amazonense, sobretudo a de Manaus, que hoje responde por mais de 50% do PIB do estado do Amazonas. A Zona Franca está em transformação; desde os anos 80 do século XX, vêm sendo reduzidos os incentivos presentes na sua origem. Isso se deve, entre outras razões, à contestação feita por outros estados às vantagens fiscais concedidas ao Amazonas. Com relação a esse assunto, assinale a opção correta.", ["A maior vantagem obtida pela Zona Franca de Manaus sempre foi a isenção de impostos para a exportação de seus produtos.", "A contestação citada no texto pode ser entendida como parte da chamada guerra fiscal entre estados brasileiros.", "O Pólo Industrial de Manaus tradicionalmente concentra-se na produção de bens primários, como os alimentícios.", "A proliferação de hidrelétricas na bacia amazônica estimula a industrialização não só em Manaus, mas também em outras cidades do Amazonas.", "Em geral, tal como ocorre no Amazonas, a população da região Norte é desconcentrada, disseminada pelo interior."], "B", "Estados que se sentiam prejudicados pelas vantagens fiscais do Amazonas contestavam esses incentivos: é a chamada guerra fiscal. A erra: o atrativo central foi a isenção para importar insumos e vender no mercado interno. C erra: o Polo Industrial produz bens industrializados (eletroeletrônicos, motocicletas), não bens primários. D não tem base. E erra: a população do Amazonas se concentra em Manaus.", ""],
  [30, 1, "atualidades", "Questão agrária", [], "Os três religiosos paraenses ameaçados de morte, segundo denúncia da Conferência Nacional dos Bispos do Brasil (CNBB) à Anistia Internacional, estão na linha de frente da luta pelos direitos humanos. Um deles, o bispo de Xingu, se destaca na luta pelos direitos indígenas e contra os grileiros que agem no sudeste do Pará, principalmente em Altamira. As ameaças ao bispo de Abaetetuba vieram após o religioso ter denunciado o caso da menina de 16 anos mantida em um cárcere masculino. Outro religioso ameaçado é um frei, advogado da Comissão Pastoral da Terra em Xinguara, no sul do Pará, há décadas engajado na luta dos trabalhadores rurais sem terra por reforma agrária.\n\nO Globo, 12/4/2008, p. 12 (com adaptações).\n\nTendo o texto acima como referência inicial e considerando a abrangência do tema por ele tratado, julgue os itens seguintes.\n\nI A questão da terra sempre foi tema explosivo no Brasil e ganhou maior intensidade a partir de meados do século passado, quando o tema da reforma agrária entrou na agenda política do país.\n\nII Deduz-se do texto que os três religiosos ora ameaçados defendem uma solução conciliatória, de modo que posseiros e grileiros possam ser atendidos e respeitados em seus direitos.\n\nIII O incidente de Abaetetuba ganhou visibilidade ao ser amplamente noticiado, e o fato de uma adolescente ter sido encarcerada junto a homens, que a violentaram no cárcere, gerou repulsa em amplos setores da sociedade.\n\nIV A inexistência de assentamentos rurais na região amazônica funciona como estopim que incendeia o cenário de tensão existente em várias localidades, entre as quais estão o sul e o sudeste do Pará.\n\nV Há consenso entre os especialistas de que o enfrentamento adequado do problema fundiário na região Norte e no país exige a criação de órgão específico da administração federal para tratar da reforma agrária.\n\nA quantidade de itens certos é igual a", ["1.", "2.", "3.", "4.", "5."], "B", "Estão certos só I e III. I: a terra é tema explosivo, e a reforma agrária entrou na agenda política em meados do século XX. III: o caso da adolescente presa com homens teve grande repercussão. II erra: os religiosos estão de um lado do conflito, contra os grileiros. IV erra: existem assentamentos rurais na Amazônia. V erra: o órgão federal já existe (INCRA), e não há esse consenso.", ""],
  [33, 1, "info", "Software livre", [], "Com relação a software livres, suas licenças de uso, distribuição e modificação, assinale a opção correta, tendo como referência as definições e os conceitos atualmente empregados pela Free Software Foundation.", ["Todo software livre deve ser desenvolvido para uso por pessoa física em ambiente com sistema operacional da família Linux, devendo haver restrições de uso a serem impostas por fornecedor no caso de outros sistemas operacionais.", "O código-fonte de um software livre pode ser adaptado ou aperfeiçoado pelo usuário, para necessidades próprias, e o resultado de aperfeiçoamentos desse software pode ser liberado e redistribuído para outros usuários, sem necessidade de permissão do fornecedor do código original.", "Toda licença de software livre deve estabelecer a liberdade de que esse software seja, a qualquer momento, convertido em software proprietário e, a partir desse momento, passem a ser respeitados os direitos de propriedade intelectual do código-fonte do software convertido.", "Quando a licença de um software livre contém cláusula denominada copyleft, significa que esse software, além de livre, é também de domínio público e, dessa forma, empresas interessadas em comercializar versões não-gratuitas do referido software poderão fazê-lo, desde que não haja alterações nas funcionalidades originais do software.", "Um software livre é considerado software de código aberto quando o seu código-fonte está disponível em sítio da Internet com designação .org, podendo, assim, ser continuamente atualizado, aperfeiçoado e estendido às necessidades dos usuários, que, para executá-lo, devem compilá-lo em seus computadores pessoais. Essa característica garante a superioridade do software livre em face dos seus concorrentes comerciais proprietários."], "B", "As quatro liberdades da Free Software Foundation são executar, estudar e adaptar, redistribuir e aperfeiçoar e liberar as melhorias, sem pedir licença ao autor. A erra: o software livre não se limita ao Linux nem à pessoa física. C erra: a licença não garante a conversão em proprietário. D erra: o copyleft obriga as versões derivadas a continuarem livres; não é domínio público. E erra: código aberto não depende de sítio .org nem de compilação pelo usuário.", ""],
  [36, 1, "info", "Correio eletrônico", [], "Em cada um dos itens a seguir, é apresentada uma forma de endereçamento de correio eletrônico.\n\nI pedro@gmail.com\n\nII ftp6maria@hotmail:www.servidor.com\n\nIII joao da silva@servidor:linux-a-r-w\n\nIV www.gmail.com/paulo@\n\nV mateus.silva@cespe.unb.br\n\nComo forma correta de endereçamento de correio eletrônico, estão certas apenas as apresentadas nos itens", ["I e II.", "I e V.", "II e IV.", "III e IV.", "III e V."], "B", "Endereço de e-mail tem a forma usuario@dominio, sem espaços e com o domínio depois da arroba. I (pedro@gmail.com) e V (mateus.silva@cespe.unb.br) estão nesse formato. II tem dois-pontos e “www” no domínio, III tem espaços e dois-pontos, e IV é endereço de página com a arroba no fim.", ""],
  [40, 1, "info", "Segurança da informação", [], "Com relação a vírus de computador, phishing, pharming e spam, julgue os itens seguintes.\n\nI Uma das vantagens de serviços webmail em relação a aplicativos clientes de correio eletrônico tais como o Mozilla Thunderbird™ 2 está no fato de que a infecção por vírus de computador a partir de arquivos anexados em mensagens de e-mail é impossível, já que esses arquivos são executados no ambiente do sítio webmail e não no computador cliente do usuário.\n\nII Phishing e pharming são pragas virtuais variantes dos denominados cavalos-de-tróia, se diferenciando destes por precisarem de arquivos específicos para se replicar e contaminar um computador e se diferenciando, entre eles, pelo fato de que um atua em mensagens de e-mail trocadas por serviços de webmail e o outro, não.\n\nIII O uso de firewall e de software antivírus é a única forma eficiente atualmente de se implementar os denominados filtros anti-spam.\n\nIV Se o sistema de nomes de domínio (DNS) de uma rede de computadores for corrompido por meio de técnica denominada DNS cache poisoning, fazendo que esse sistema interprete incorretamente a URL (uniform resource locator) de determinado sítio, esse sistema pode estar sendo vítima de pharming.\n\nV Quando enviado na forma de correio eletrônico para uma quantidade considerável de destinatários, um hoax pode ser considerado um tipo de spam, em que o spammer cria e distribui histórias falsas, algumas delas denominadas lendas urbanas.\n\nA quantidade de itens certos é igual a", ["1.", "2.", "3.", "4.", "5."], "B", "Estão certos só IV e V. IV: corromper o DNS (DNS cache poisoning) para mandar o usuário a um sítio falso é pharming. V: o hoax (boato) mandado em massa é um tipo de spam. I erra: o anexo baixado do webmail pode infectar o computador. II erra: phishing e pharming são golpes de fraude, não variantes do cavalo de troia. III erra: filtro anti-spam não depende só de firewall e antivírus.", ""],
  [43, 1, "transito", "Placas de veículos oficiais", [], "A Resolução n.º 32/1998 do CONTRAN aprovou modelos de placa para veículos de representação de diversas autoridades. Acerca dessas placas, assinale opção correta.", ["Os prefeitos municipais podem determinar os modelos de placas de veículos oficiais utilizados por ele e sua equipe, o que se explica pelo princípio da separação dos poderes.", "Os modelos de placas dos veículos oficiais de representação de governador de estado ou do DF serão, necessariamente, diferentes dos modelos de seus vices.", "Os modelos de placas de representação para veículos oficiais dos ministros dos tribunais serão utilizados mediante solicitação dos presidentes dessas cortes.", "Nos veículos oficiais utilizados por prefeitos municipais, as placas terão fundo vermelho e letras e números em branco, sendo opcional o emblema da unidade federativa.", "A resolução mencionada permite que as dimensões das placas de veículo oficial sejam livremente escolhidas pela autoridade que utilizará o veículo."], "C", "A Resolução 32/1998 previa que as placas de representação dos ministros dos tribunais seriam usadas a pedido dos presidentes das cortes. As outras opções não correspondem à resolução: modelos, cores e dimensões das placas são fixados pelo CONTRAN, sem escolha da autoridade.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [44, 1, "transito", "Sinalização de veículo imobilizado", [], "Um veículo parado no leito da via pode atrapalhar o fluxo de veículos, além de possibilitar a ocorrência de acidentes. Por esse e outros motivos, o CTB prescreve as providências a serem tomadas para a imediata sinalização de advertência, como estabelecida pelo CONTRAN. Acerca dessas providências, assinale a opção correta.", ["A imobilização de veículo no leito viário, em situação de emergência, deverá ser sinalizada imediatamente, podendo o veículo, bem sinalizado, permanecer na via por, no máximo, uma hora.", "Na condição citada, o condutor deverá acionar de imediato as luzes de advertência (pisca-alerta) e colocar o triângulo de sinalização, ou equipamento similar, preso junto ao pára-choque traseiro do veículo.", "Na situação considerada, o equipamento de sinalização de emergência deverá ser instalado perpendicularmente ao eixo da via, e em condição de boa visibilidade.", "Na ausência do triângulo de segurança, a resolução referida indica a utilização de galhos vegetais para sinalização do veículo imobilizado no leito da via, já que ambos os dispositivos cumprem formalmente o mesmo objetivo.", "Ônibus ou caminhões imobilizados temporariamente no leito viário devem usar pelo menos dois triângulos para sinalização dos veículos."], "C", "O triângulo (ou equipamento similar) deve ficar perpendicular ao eixo da via, em condição de boa visibilidade e a distância do veículo. B erra: o triângulo não fica preso ao para-choque. A erra: não há prazo de uma hora. D erra: galhos não substituem o equipamento de sinalização. E traz exigência que a norma não faz.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [45, 1, "transito", "Medidas administrativas", [], "Um caminhão que transportava carga perigosa foi abordado por um PRF. Durante a abordagem, o PRF constatou irregularidade administrativa que ensejava a apreensão do veículo e seu recolhimento ao depósito. Diante dessa situação, assinale a opção correta acerca dos critérios para a realização da apreensão do veículo e seu recolhimento ao depósito, conforme resolução do CONTRAN.", ["Cabe ao PRF emitir termo de apreensão do veículo, que discriminará os equipamentos obrigatórios eventualmente ausentes, o estado geral da lataria e da pintura, os danos causados por acidente, se for o caso, a identificação do proprietário e do condutor, quando possível, e dados que permitam a precisa identificação do veículo. A discriminação dos objetos que se encontrem no veículo é opcional.", "O termo de apreensão do veículo deve ser preenchido pelo PRF, em duas vias: a primeira via será entregue ao proprietário ou condutor do veículo apreendido e a segunda, ao órgão ou entidade responsável pela custódia do veículo.", "Por ser documento do proprietário do veículo, o PRF não deverá recolher o CRLV.", "Caso a penalidade aplicada ao abordado pelo PRF tenha sido aplicada em razão de infração para a qual seja prevista multa agravada com fator multiplicador de três vezes, então o prazo da custódia será de 21 a 30 dias.", "Desde que o veículo ofereça condições de segurança para circulação em via pública, o PRF poderá dispensar sua retenção imediata."], "E", "A resolução sobre apreensão permitia dispensar a retenção imediata quando o veículo oferecesse condições de segurança para circular. A erra no fim: a relação dos objetos encontrados no veículo é obrigatória no termo, não opcional. As demais trocam detalhes do procedimento (vias do termo, recolhimento do CRLV e prazos de custódia).", "Depois da prova, a Lei 13.281/2016 revogou a penalidade de apreensão do veículo (CTB, art. 256, IV, e art. 262); hoje a medida usada é a remoção. A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [46, 1, "transito", "Transporte de passageiros em veículo de carga", [], "Acerca do transporte de passageiros em veículos de carga, assinale a opção incorreta.", ["O transporte de passageiros em veículos de carga, remunerado ou não, poderá ser autorizado eventualmente e a título precário.", "A autorização para transporte de passageiros em veículos de carga não pode ser concedida para viagem cuja data ultrapasse a validade do CRLV.", "As migrações internas decorrentes de assentamento agrícola de responsabilidade do governo e as viagens por motivos religiosos, quando não houver condições de atendimento por transporte de ônibus, são hipóteses tratadas como exceção para fins de transporte de passageiros em veículos de carga.", "São duas as condições mínimas para a concessão de autorização para o transporte de pessoas em veículos de carga: carroceria, com guardas altas em todo o seu perímetro, fabricadas em material de boa qualidade e resistência estrutural, e cobertura com estrutura em material de resistência adequada.", "Para o transporte de passageiros em veículos de carga não poderão ser utilizados os denominados basculantes e os boiadeiros."], "D", "A questão pede a incorreta. A resolução exige mais do que carroceria com guardas altas e cobertura: a resolução lista outros requisitos de segurança. Por isso a D, que fala em “duas condições mínimas”, está errada. As demais reproduzem a norma: autorização eventual e a título precário, validade limitada ao CRLV, exceções (assentamentos, viagens religiosas) e proibição de basculantes e boiadeiros.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [47, 1, "transito", "Licenciamento anual", [], "Resolução do CONTRAN estabelece um calendário determinando os prazos finais em que os veículos devem renovar o licenciamento anual. A respeito desse assunto, assinale a opção correta.", ["O órgão executivo de trânsito de um município pode estabelecer um calendário diverso do definido pelo CONTRAN, desde que não haja um calendário definido pelo órgão executivo estadual.", "O órgão executivo de trânsito de um estado pode estabelecer um calendário diverso do definido pelo CONTRAN para a renovação do licenciamento dos veículos registrados sob sua circunscrição, desde que o prazo final para a renovação seja anterior a 1.º de julho.", "Para efeito de autuação e aplicação de penalidades referentes a não renovação de licenciamento anual de veículos, quando o veículo se encontrar em unidade da Federação diferente daquela em que estiver registrado, serão adotados os prazos estabelecidos pela resolução pertinente do CONTRAN.", "De acordo com o referido calendário, o último dia de janeiro é o prazo final para a renovação do licenciamento dos veículos cujas placas de identificação terminem em 0 e 1.", "De acordo com o referido calendário, o último dia de junho é o prazo final para a renovação do licenciamento dos veículos cujas placas de identificação terminem em 6."], "C", "Fora da unidade da Federação de registro, a fiscalização do licenciamento usa os prazos do calendário do CONTRAN. A erra: o licenciamento é feito pelo órgão estadual, não pelo municipal. B, D e E erram os prazos do calendário, que ia de setembro a dezembro conforme o final da placa.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [48, 1, "transito", "Equipamentos de segurança", [], "A respeito dos dispositivos de segurança para prover melhores condições de visibilidade diurna e noturna em veículos de transporte de carga, assinale a opção correta.", ["Os veículos de transporte de carga com peso bruto total superior a 4.536 kg, fabricados a partir de 30/4/2001, somente poderão ser comercializados quando possuírem dispositivo de segurança afixado de acordo com as disposições da resolução do CONTRAN relativa ao assunto.", "O registro e o licenciamento de veículo que está obrigado a instalar dispositivo de segurança destinado a prover melhores condições de visibilidade podem ser realizados mesmo em caso de inobservância das disposições regulamentares, desde que o proprietário se comprometa formalmente a realizar a instalação em, no máximo, 120 dias após a aquisição do veículo.", "Os requisitos estabelecidos pelo CONTRAN acerca desse assunto, na inspeção de segurança veicular, são itens de verificação opcional.", "As exigências estabelecidas pelo CONTRAN para prover melhores condições de visibilidade diurna e noturna em veículos de transporte de carga estendem-se também aos veículos militares.", "Sem os referidos dispositivos de segurança afixados, os veículos de carga apenas podem circular no período matutino."], "A", "A resolução exigia dispositivo refletivo nos veículos de carga com PBT acima de 4.536 kg fabricados a partir de 30/4/2001, sem o qual não podiam ser comercializados. B erra: sem o dispositivo não há registro nem licenciamento. C erra: o item é de verificação obrigatória. D estende a exigência além do que a resolução previa, e E não tem base.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [49, 1, "transito", "Sinalização", [], "Assinale a opção correta relativa à sinalização de trânsito.", ["A sinalização vertical, quando classificada de acordo com sua função, compreende a sinalização de regulamentação, a sinalização de perigo e a sinalização de indicação.", "A sinalização vertical é um subsistema da sinalização viária cujo meio de comunicação está na posição vertical, normalmente em placa, fixado ao lado ou suspenso sobre a pista, transmitindo mensagens de caráter permanente e, eventualmente, variáveis, por meio de legendas e(ou) símbolos pré-reconhecidos e legalmente instituídos.", "A forma padrão do sinal de regulamentação é a circular, e as cores são amarela e preta.", "A forma padrão dos sinais de perigo é a quadrada, em que nenhuma das bordas fica na posição paralela ao solo.", "A sinalização horizontal é um subsistema da sinalização viária que se utiliza de linhas, marcações, símbolos e legendas, pintados ou apostos sobre o pavimento das vias, e que não possuem qualquer poder de regulamentação."], "B", "É a definição de sinalização vertical do Anexo II do CTB. A erra a classificação: regulamentação, advertência e indicação (não “perigo”). C erra as cores: regulamentação é vermelho, branco e preto; amarelo e preto é advertência. D usa “sinais de perigo”, classe que o CTB não tem: a forma descrita (quadrado com uma das diagonais na vertical) é a do sinal de advertência. E erra: a sinalização horizontal também regulamenta.", ""],
  [52, 1, "transito", "Fiscalização eletrônica", [], "Em uma capital brasileira foi instalado um aparelho eletrônico que registra e processa dados decorrentes do fluxo de automóveis em velocidade acima do permitido para o local. Esse equipamento registrou duas infrações na manhã do dia 12/8/2008, uma praticada por condutor de veículo registrado em nome de repartição consular de carreira e outra praticada por condutor de veículo registrado em nome de sociedade de arrendamento mercantil. Diante dessa situação hipotética, assinale a opção correta.", ["Comprovada a ocorrência de infração por equipamento audiovisual, aparelho eletrônico ou por outro meio ainda que não seja regulamentado pelo CONTRAN, será lavrado o auto de infração de trânsito que deverá conter os dados mínimos definidos pelo CTB.", "O auto de infração, nesse caso, será lavrado posteriormente pela autoridade de trânsito por anotação em documento próprio.", "A comprovação da infração ocorrida exige referendo por agente da autoridade de trânsito.", "No caso de veículo registrado em nome de repartição consular de carreira, a notificação da autuação deverá ser remetida ao Ministério das Relações Exteriores, para as providências cabíveis, passando a correr os prazos a partir da entrega ao referido ministério.", "No caso de veículo registrado em nome de sociedade de arrendamento mercantil, o órgão ou entidade de trânsito deverá encaminhar a notificação da autuação diretamente a esta, que, para os fins da resolução pertinente do CONTRAN, equipara-se ao proprietário do veículo."], "C", "A banca deu como certa a C. Por eliminação: A erra porque o equipamento tem de ser regulamentado pelo CONTRAN (CTB, art. 280, § 2º); D erra porque, nos veículos de repartição consular, os prazos correm do conhecimento pelo proprietário, não da entrega ao Ministério; E erra porque a notificação vai ao arrendatário, que se equipara ao proprietário. B descreve um procedimento que a norma não previa para esse caso.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [53, 1, "transito", "Equipamentos de segurança", [], "Acerca dos requisitos técnicos de fabricação e instalação de pára-choque traseiro para veículos de carga, assinale a opção correta.", ["Todos os veículos de carga fabricados no país, importados ou encarroçados a partir de 1.º/7/2004 somente poderão ser registrados e licenciados se estiverem dotados do pára-choque traseiro que atenda às especificações do CONTRAN.", "O veículo de carga com peso bruto total superior a 4.600 kg, cujas características originais da carroçaria forem alteradas, ou em que for instalado algum tipo de implemento a partir de 1.º/7/2004, deverá atender às especificações constantes do anexo da resolução do CONTRAN que trata dos requisitos técnicos de fabricação e instalação de pára-choque traseiro para veículos de carga.", "Estão também sujeitos ao cumprimento dos referidos requisitos estabelecidos pelo CONTRAN os veículos destinados à exportação e os caminhões-tratores.", "Os veículos produzidos especialmente para cargas autoportantes ou outros itens muito longos equiparam-se para os efeitos da aplicação dos requisitos estabelecidos pelo CONTRAN ao veículo de carga com peso bruto total superior a 4.600 kg cujas características originais da carroçaria forem alteradas.", "Os carros de coleção, a partir de 1.º/7/2004, somente poderão ser registrados e licenciados se estiverem dotados do pára-choque traseiro que atenda às especificações de resolução do CONTRAN."], "B", "Veículos de carga com PBT acima de 4.600 kg que tivessem a carroçaria alterada ou implemento instalado a partir de 1º/7/2004 tinham de seguir as especificações do para-choque traseiro. A erra ao dizer “todos”: a resolução tem exceções. C, D e E citam justamente veículos que a resolução deixava de fora (exportação, caminhões-tratores, cargas autoportantes, carros de coleção).", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [54, 1, "transito", "Conceitos do CTB", [], "Julgue os itens a seguir, relativos a conceitos utilizados para a interpretação do CTB.\n\nI Caminhonete — veículo misto destinado ao transporte de passageiros e carga no mesmo compartimento.\n\nII Ilha — obstáculo físico, colocado na pista de rolamento, destinado à ordenação dos fluxos de trânsito em uma interseção.\n\nIII Tara — peso próprio do veículo, acrescido dos pesos da carroçaria e equipamento, do combustível, das ferramentas e acessórios, da roda sobressalente, do extintor de incêndio e do fluido de arrefecimento, expresso em quilogramas.\n\nIV Veículo de grande porte — veículo automotor destinado ao transporte de carga com peso bruto total máximo superior a 10.000 kg e de passageiros, superior a vinte passageiros.\n\nA quantidade de itens certos é igual a", ["0.", "1.", "2.", "3.", "4."], "D", "Três itens estão certos. I está errado: veículo misto de passageiros e carga no mesmo compartimento é a camioneta; caminhonete é veículo de carga de até 3.500 kg (Anexo I do CTB). II (ilha), III (tara) e IV (veículo de grande porte: carga acima de 10.000 kg ou mais de 20 passageiros) reproduzem o Anexo I.", ""],
  [55, 1, "transito", "Fiscalização eletrônica", [], "Acerca da regulamentação do CONTRAN para utilização de sistemas automáticos não metrológicos de fiscalização, nos termos do CTB, assinale a opção correta.", ["O sistema automático não metrológico de fiscalização não precisa ter sua conformidade avaliada pelo INMETRO, ou entidade por ele acreditada.", "A imagem detectada pelo sistema automático não metrológico de fiscalização deve permitir a identificação do veículo e, no mínimo, registrar a placa do veículo e o dia da infração, não sendo necessário, portanto, constar o horário da infração.", "A imagem detectada pelo sistema automático não metrológico de fiscalização deve permitir a identificação do veículo, mas não é necessário registrar o local da infração.", "Compete à autoridade de trânsito com circunscrição sobre a via dispor sobre a localização, instalação e operação de sistema automático não metrológico de fiscalização. Quando utilizado esse tipo de sistema na fiscalização, é obrigatória a presença da autoridade ou do agente da autoridade de trânsito no local da infração.", "Antes de efetivar o uso do sistema para a fiscalização de infrações decorrentes da inobservância de sinalização, a autoridade de trânsito com circunscrição sobre a via deverá verificar se a sinalização de regulamentação de trânsito exigida pela legislação está em conformidade com essa legislação."], "E", "Antes de usar o sistema para infrações de sinalização, a autoridade deve conferir se a sinalização de regulamentação está de acordo com a legislação. A erra: o sistema precisa de avaliação do INMETRO. B e C erram: o registro deve trazer placa, data, hora e local. D erra: o sistema automático dispensa a presença do agente.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [56, 1, "transito", "Habilitação", [], "Acerca das normas e dos procedimentos para a formação de condutores de veículos automotores e elétricos, da realização dos exames, da expedição de documentos de habilitação, dos cursos de formação, especializados e de reciclagem e outras providências, assinale a opção correta de acordo com resolução pertinente do CONTRAN.", ["O candidato à obtenção da ACC ou da CNH não precisa ser alfabetizado nem possuir documento de identidade ou CPF para obter êxito na obtenção de sua autorização.", "Uma pessoa não poderá requerer simultaneamente a ACC e habilitação na categoria B, bem como requerer habilitação em A e B submetendo-se a um único exame de aptidão física e mental e avaliação psicológica, mesmo que considerada apta para ambas.", "Para a obtenção da ACC e da CNH, o candidato deverá submeter-se a avaliação psicológica, que, por sua vez, substitui o exame de aptidão física e mental.", "O condutor de veículo automotor, natural de país estrangeiro e nele habilitado, em estada regular, desde que penalmente imputável no Brasil, poderá dirigir no território nacional quando amparado por convenções ou acordos internacionais ratificados e aprovados pela República Federativa do Brasil.", "Quando um condutor habilitado em país estrangeiro cometer infração de trânsito cuja penalidade implique a proibição do direito de dirigir, a autoridade competente de trânsito não poderá recolher e reter o documento de habilitação do infrator."], "D", "O condutor estrangeiro habilitado no seu país, em estada regular e penalmente imputável no Brasil, pode dirigir aqui quando amparado por convenção ou acordo internacional (CTB, art. 142). A erra: o candidato precisa saber ler e escrever e ter identidade e CPF (art. 140). B erra: era possível pedir ACC e categoria B ao mesmo tempo. C erra: a avaliação psicológica não substitui o exame de aptidão física e mental. E erra: o documento estrangeiro pode ser recolhido.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [57, 1, "transito", "Documentos de porte obrigatório", [], "Josué perdeu o CLRV de seu veículo e dirigiu-se ao departamento de trânsito do seu estado em busca da emissão de um novo documento de registro e licenciamento. Diante dessa situação hipotética, assinale a opção correta.", ["O CRLV, juntamente com a CNH, é documento de porte obrigatório do condutor, razão pela qual Josué agiu corretamente ao procurar o departamento de trânsito estadual para resolver a situação.", "Não será possível a expedição de uma via original do CRLV, diante da solicitação de Josué, o qual deverá utilizar uma cópia autenticada pelo departamento de trânsito.", "A expedição de documento hábil, ainda que provisório, que permita a Josué dirigir o seu veículo deve ser efetivada pelo órgão de trânsito em 48 horas.", "Se Josué vier a dirigir seu veículo sem o CRLV, estará cometendo uma infração de trânsito média.", "Caso Josué dirija o veículo sem o CRLV, ficará sujeito ao pagamento da penalidade de multa, mas não estará sujeito à retenção do veículo."], "A", "O CRLV e a CNH eram de porte obrigatório (CTB, art. 133 e art. 159, § 1º), então Josué fez certo ao pedir a segunda via. B erra: a segunda via original pode ser expedida. C cria um prazo de 48 horas que o CTB não prevê. D erra: dirigir sem o documento é infração leve (art. 232). E erra: além da multa, há retenção do veículo até a apresentação do documento.", "Depois da prova, a Lei 13.281/2016 incluiu parágrafo único no art. 133: o porte do CRLV fica dispensado quando o agente puder consultar o sistema no local. Hoje o CRLV é digital. O enunciado escreve “CLRV”; foi mantido como aplicado."],
  [58, 1, "transito", "Transporte de veículos (CTV)", [], "Acerca dos requisitos de segurança necessários à circulação de combinações para transporte de veículos (CTV), estabelecidos na Resolução n.º 274/2008 do CONTRAN, assinale a opção correta.", ["As CTV, construídas e destinadas exclusivamente ao transporte de veículos, cujas dimensões excedam aos limites regulamentares não poderão circular nas vias públicas.", "O conceito mais completo para CTV é aquele segundo o qual esta se constitui do veículo ou da combinação de veículos adaptados especialmente para o transporte de automóveis, vans, ônibus e caminhões.", "A circulação de CTV deverá ocorrer obrigatoriamente sempre do amanhecer ao pôr-do-sol e sua velocidade máxima será de 80 km/h.", "A AET, expedida pela autoridade competente, terá validade máxima de um ano e somente será concedida após vistoria técnica da CTV, expedida pelo órgão executivo rodoviário da União, que fornecerá o cadastro aos órgãos e entidades executivas rodoviárias dos estados, do DF e dos municípios.", "A partir do momento em que é concedida autorização especial de trânsito para CTV pelo órgão administrativo, o proprietário e o condutor do veículo se tornam isentos de eventuais danos que o veículo venha causar à via, à sua sinalização e a terceiros em decorrência do seu peso bruto total e(ou) das suas demais dimensões."], "D", "A AET da CTV vale até um ano e só é concedida depois de vistoria técnica. A erra: a CTV que excede as dimensões circula com AET. B não é o conceito da resolução. C cria horário e velocidade fixos para todos os casos. E erra: a AET não isenta proprietário e condutor dos danos causados.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [60, 1, "transito", "Competências da PRF", [], "As competências da PRF, no âmbito das rodovias e estradas federais, não incluem", ["realizar o patrulhamento ostensivo, mediante a execução de operações relacionadas com a segurança pública, com o objetivo de preservar a ordem, a incolumidade das pessoas, o patrimônio da União e o de terceiros.", "aplicar e arrecadar as multas impostas por infrações de trânsito, as medidas administrativas decorrentes e os valores provenientes de estada e remoção de veículos, objetos, animais e escolta de veículos de cargas superdimensionadas ou perigosas.", "realizar o patrulhamento ostensivo das ferrovias federais que margeiam as rodovias federais.", "integrar-se a outros órgãos e entidades do SNT para fins de arrecadação e compensação de multas impostas na área de sua competência, com vistas à unificação do licenciamento, à simplificação e à celeridade das transferências de veículos e de prontuários de condutores de uma para outra unidade da Federação.", "coletar dados estatísticos e elaborar estudos sobre acidentes de trânsito e suas causas, adotando ou indicando medidas operacionais preventivas e encaminhando-os ao órgão rodoviário federal."], "C", "O patrulhamento ostensivo das ferrovias federais cabe à polícia ferroviária federal (CF, art. 144, § 3º), não à PRF. As demais opções estão entre as competências da PRF no CTB (art. 20) e no regimento da época: patrulhamento ostensivo, aplicação e arrecadação de multas e valores de estada e remoção, integração com o SNT e estatísticas de acidentes.", "A PEC 18/2025 (PEC da Segurança Pública), aprovada pelo Senado em 3/11/2026 e ainda à espera de promulgação, estende a atuação da PRF às ferrovias e hidrovias federais. Se for promulgada, este item terá de ser revisto."],
  [61, 1, "transito", "Pesagem de veículos", [], "Assinale a opção correta com relação à metodologia de aferição do peso de veículos estabelecida em resolução pertinente do CONTRAN.", ["Para efeito da classificação do veículo, o comprimento total é aquele medido do ponto mais avançado da extremidade dianteira do veículo ao ponto mais avançado da sua extremidade traseira, não incluídos os acessórios.", "A fiscalização de peso dos veículos deve ser feita por equipamento de pesagem (balança rodoviária) ou, na impossibilidade, pela verificação de documento fiscal.", "Quando o peso verificado estiver acima do peso bruto total ou do peso bruto total combinado, estabelecido para o veículo, acrescido da tolerância de 5%, aplicar-se-á a multa somente sobre a parcela que exceder essa tolerância, desde que não ultrapasse o limite de 10% do peso máximo permitido, sendo, nesse caso, possível que o veículo prossiga a viagem depois de efetuado o pagamento.", "Nos casos em que não for possível, no local da fiscalização, o remanejamento ou transbordo da carga, por ser esta perecível, o veículo deverá ser recolhido ao depósito, com a carga, e só serão liberados o veículo e a carga após sanada a irregularidade e pagas todas as despesas de remoção e estada.", "O agente da autoridade de trânsito competente designado para lavrar o auto de infração decorrente de excesso de peso não poderá ser servidor civil celetista."], "B", "A pesagem é feita em balança rodoviária ou, na impossibilidade, pela nota fiscal. E erra: o agente que lavra o auto pode ser servidor civil, estatutário ou celetista, ou policial militar (CTB, art. 280, § 4º). A, C e D trocam detalhes da resolução (medição do comprimento, cálculo da multa e liberação de carga perecível).", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [62, 1, "transito", "Modificação de veículos", [], "Acerca das modificações de veículos previstas pelo CTB e regulamentadas pelo CONTRAN, assinale a opção correta.", ["As modificações em veículos não se submetem a autorização prévia da autoridade responsável pelo registro e licenciamento, desde que estejam em conformidade com as previsões legais.", "É vedada a modificação da estrutura original de fábrica de um veículo movido a gasolina para aumentar a capacidade de carga, visando o uso do combustível dísel.", "Na modificação da suspensão do veículo, podem ser utilizados sistemas de suspensão com regulagem de altura.", "O uso do gás natural veicular como combustível é permitido, para fins automotivos, inclusive para ciclomotores, motonetas, motocicletas e triciclos, desde que os componentes do sistema estejam certificados pelo Sistema Brasileiro de Avaliação da Conformidade.", "A substituição do chassi ou monobloco de veículo por outro chassi ou monobloco pode ser realizada em caso de furto, roubo ou sinistro do veículo."], "B", "Era proibido alterar a estrutura de veículo a gasolina para aumentar a capacidade de carga e passar a usar diesel. A erra: a modificação exige autorização prévia (CTB, art. 98). C erra: a resolução proibia suspensão com regulagem de altura. D erra: o GNV não era permitido em ciclomotores, motonetas, motocicletas e triciclos. E também não corresponde à norma da época.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [63, 1, "transito", "Transporte de crianças", [], "Em uma rodovia federal, João conduzia um automóvel de quatro portas, com cinco lugares, com 4 crianças dentro, todas com menos de 10 anos de idade. Um PRF deu sinal de parada e abordou o citado automóvel para fiscalização. O veículo era um táxi em que João estava transportando as crianças com autorização dos pais, que vinham em outro automóvel, logo atrás, transportando mais três crianças. Ao verificar a existência de uma criança com menos de 10 anos de idade no banco dianteiro do carro, o PRF solicitou que todas as crianças descessem do automóvel e se colocassem uma ao lado da outra. O PRF verificou que a criança que estava sentada na frente era a mais velha entre todas, pois tinha 9 anos e 10 meses de idade, mas não era a mais alta, pois havia uma criança de 9 anos e um mês de idade que possuía maior estatura. Além do mais, a criança sentada à frente estava usando cinto de segurança, mas as de trás, não. Havia também no táxi uma criança de 7 anos de idade. Tendo por base essa situação hipotética e as regras de transporte de menores de 10 anos de idade e de utilização do dispositivo de retenção para o transporte de crianças em veículo, assinale a opção incorreta.", ["Para transitar em veículos automotores, todas as crianças que estavam no automóvel deveriam estar usando individualmente cinto de segurança ou sistema de retenção equivalente.", "O transporte de crianças em veículo automotor sem observância das normas de segurança especiais estabelecidas no CTB constitui infração gravíssima.", "Na hipótese de a quantidade de crianças com idade inferior a dez anos exceder a capacidade de lotação do banco traseiro, o condutor deveria ter transportado aquela de maior estatura, e não a mais velha, no banco dianteiro, utilizando o cinto de segurança do veículo ou dispositivo de retenção adequado ao seu peso e à altura.", "As exigências relativas ao sistema de retenção, no transporte de crianças com até sete anos e meio de idade, também se aplicam à atividade de transporte autônomo de passageiro (táxi).", "Se transportar crianças em veículo automotor sem observância das normas de segurança, o condutor estará sujeito à penalidade de multa e à retenção do veículo até que a irregularidade seja sanada."], "D", "A questão pede a incorreta. A resolução do CONTRAN sobre dispositivo de retenção deixava o táxi de fora dessa exigência, por isso a D está errada. As demais estão de acordo com o CTB e a resolução: crianças com cinto ou retenção, infração gravíssima (art. 168), a de maior estatura na frente quando o banco de trás lota, e multa com retenção do veículo.", "Depois da prova, a Lei 14.071/2020 mudou o art. 64 do CTB: hoje vão no banco traseiro as crianças com menos de 10 anos que não tenham atingido 1,45 m de altura. A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [64, 1, "transito", "Sistema Nacional de Trânsito", [], "Julgue os itens subseqüentes com respeito ao SNT.\n\nI Os órgãos e entidades componentes do SNT respondem, no âmbito das respectivas competências, objetivamente, por danos causados aos cidadãos em virtude de ação, omissão ou erro na execução e manutenção de programas, projetos e serviços que garantam o exercício do direito do trânsito seguro.\n\nII O SNT é o conjunto de órgãos e entidades da União, dos estados, do DF e dos municípios que tem por finalidade o exercício das atividades de planejamento, administração, normatização, pesquisa, registro e licenciamento de veículos, formação, habilitação e reciclagem de condutores, educação, engenharia, operação do sistema viário, policiamento, fiscalização, julgamento de infrações e de recursos e aplicação de penalidades.\n\nIII Compõem o SNT: o CONTRAN, os conselhos estaduais de trânsito (CETRAN) e o Conselho de Trânsito do Distrito Federal (CONTRANDIFE), os órgãos e entidades executivos de trânsito da União, dos estados, do DF e dos municípios, os órgãos e entidades executivos rodoviários da União, dos estados, do DF e dos municípios, a PRF, as polícias militares dos estados e do DF e as juntas administrativas de recursos de infrações.\n\nIV As Câmaras Temáticas, órgãos técnicos vinculados ao CONTRAN, são integradas por especialistas e têm como objetivo estudar e oferecer sugestões e embasamento técnico sobre assuntos específicos para decisões daquele colegiado.\n\nA quantidade de itens certos é igual a", ["0.", "1.", "2.", "3.", "4."], "E", "Os quatro itens estão certos: I é o art. 1º, § 3º (responsabilidade objetiva dos órgãos do SNT), II é o art. 5º (conceito e finalidade), III é o art. 7º (composição) e IV é o art. 13 (câmaras temáticas).", ""],
  [65, 1, "transito", "Normas de circulação", [], "Assinale a opção que está em harmonia com as normas gerais de circulação previstas no CTB.", ["Embora seja recomendável que, antes de colocar o veículo em circulação nas vias públicas, o condutor verifique a existência de combustível suficiente para chegar ao local de destino, não há no CTB previsão expressa a esse respeito.", "O trânsito de veículos nas vias terrestres abertas à circulação deve ocorrer pelo lado direito da via, não se admitindo exceções quanto a isso.", "Quando uma pista de rolamento comportar várias faixas de circulação no mesmo sentido, são as da esquerda as destinadas ao deslocamento dos veículos mais lentos e de maior porte, quando não houver faixa especial a eles destinada, e as da direita, destinadas à ultrapassagem e ao deslocamento dos veículos de maior velocidade.", "O trânsito de veículos sobre passeios e calçadas só poderá ocorrer para que se adentre ou se saia dos imóveis ou áreas especiais de estacionamento e tal restrição não se aplica aos acostamentos.", "Quando veículos, transitando por fluxos que se cruzem, se aproximarem de local não sinalizado, terá preferência de passagem, no caso de rotatória, aquele que estiver circulando por ela."], "E", "Em local sem sinalização, na rotatória, tem preferência quem já circula por ela (CTB, art. 29, III, b). A erra: o art. 27 manda verificar o combustível. B erra: o art. 29, I, admite exceções. C inverte: os mais lentos e maiores vão nas faixas da direita. D erra: a restrição do art. 29, V, vale também para os acostamentos.", ""],
  [66, 1, "transito", "Tração animal e animais na via", [], "Acerca da condução de veículos de tração animal e da circulação de animais isolados ou em grupo nas vias, assinale a opção correta de acordo com o CTB.", ["Os veículos de tração animal terão de ser conduzidos pelo lado esquerdo da pista, sempre que não houver faixa especial a eles destinada.", "Os animais isolados ou em grupos só podem circular nas vias quando conduzidos por um guia, e, para facilitar os deslocamentos, os rebanhos não devem ser divididos em grupos.", "Os animais que circularem pela pista de rolamento deverão ser mantidos junto ao bordo da pista.", "A circulação de animais sobre pontes de rodovias federais, quando em grupo, só pode ocorrer com total paralisação do trânsito de veículos.", "Compete à PRF, no âmbito das rodovias e estradas federais, aplicar e arrecadar as multas impostas por infrações de trânsito e os valores provenientes de estada e remoção de veículos e objetos, mas não os valores provenientes da remoção de animais, pois tal competência cabe à autoridade de trânsito estadual."], "C", "Os animais na pista de rolamento devem ser mantidos junto ao bordo da pista (CTB, art. 53, II). A erra: veículos de tração animal vão pela direita (art. 52). B erra: os rebanhos devem ser divididos em grupos de tamanho moderado (art. 53, I). D não está no CTB. E erra: a PRF arrecada também os valores da remoção de animais (art. 20, III).", ""],
  [67, 1, "transito", "Placas de veículos oficiais", [], "Entre as autoridades públicas apresentadas nas opções a seguir, aquela cuja placa em veículo de representação pessoal usa as cores verde e amarela da Bandeira Nacional é o", ["presidente de tribunal federal.", "governador de estado.", "procurador-geral da República.", "oficial general das Forças Armadas.", "prefeito."], "C", "Entre as opções, a placa verde e amarela das cores da Bandeira é a do procurador-geral da República, conforme a Resolução 32/1998. As demais autoridades usavam outros modelos.", "A resolução do CONTRAN cobrada era a vigente em 2008; desde então o CONTRAN revisou e consolidou suas resoluções. Confira a norma atual antes de usar esse detalhe."],
  [68, 1, "transito", "Condutor de escolares", [], "José Carlos pretende abrir uma pequena empresa para prestar serviço de condução de escolares. Para ser condutor de veículo destinado à condução de escolares, José Carlos deve satisfazer cumulativamente alguns requisitos. A propósito dessa situação hipotética, assinale a opção que reúne os requisitos que, segundo o CTB, José Carlos deve preencher.", ["Ter 18 anos, ser habilitado na categoria D, não ter cometido infração média ou ser reincidente em infrações leves durante os doze últimos meses, ser aprovado em curso especializado, nos termos de regulamentação do CONTRAN.", "Ter 21 anos, ser habilitado na categoria C, não ter cometido infração gravíssima ou ser reincidente em infrações médias durante os seis últimos meses, ser aprovado em curso especializado, nos termos de regulamentação do CONTRAN.", "Ter 25 anos, ser habilitado na categoria D, não ter cometido infração grave ou ser reincidente em infrações leves durante os doze últimos meses, ser aprovado em curso especializado, nos termos de regulamentação do CONTRAN.", "Ter 21 anos, ser habilitado na categoria D, não ter cometido infração grave ou gravíssima ou ser reincidente em infrações médias durante os doze últimos meses, ser aprovado em curso especializado, nos termos de regulamentação do CONTRAN.", "Ter 21 anos, ser habilitado na categoria C, não ter cometido infração grave ou gravíssima ou ser reincidente em infrações leves durante os seis últimos meses, ser aprovado em curso especializado, nos termos de regulamentação do CONTRAN."], "D", "O art. 138 do CTB exigia: 21 anos, categoria D, não ter cometido falta grave ou gravíssima nem ser reincidente em médias nos 12 últimos meses e curso especializado. As outras opções trocam a idade, a categoria, o tipo de infração ou o prazo.", "Depois da prova, a Lei 14.071/2020 mudou o inciso IV do art. 138: hoje o requisito é “não ter cometido mais de uma infração gravíssima nos 12 (doze) últimos meses”."],
  [69, 1, "transito", "Infrações", [], "De acordo com o CTB, constitui infração gravíssima", ["atirar do veículo ou abandonar na via objetos ou substâncias.", "deixar o condutor de prestar socorro à vítima de acidente de trânsito quando solicitado pela autoridade e seus agentes.", "dirigir veículo com CNH ou permissão para dirigir de categoria inferior à exigida para a condução do veículo que esteja conduzindo.", "ter o veículo imobilizado na via por falta de combustível.", "estacionar o veículo nas esquinas e a menos de cinco metros do bordo do alinhamento da via transversal."], "C", "Dirigir com CNH ou permissão de categoria diferente da do veículo é gravíssima (CTB, art. 162, III). Atirar objetos na via é média (art. 172), não socorrer quando solicitado pela autoridade é grave (art. 177), ficar sem combustível é média (art. 180) e estacionar a menos de 5 m da esquina é média (art. 181, II).", ""],
  [70, 1, "transito", "Crimes de trânsito", [], "De acordo com o CTB, assinale a opção correta acerca das ações penais por crimes cometidos na direção de veículos automotores.", ["Em nenhuma hipótese se admite a aplicação aos crimes de trânsito de disposições previstas na lei que dispõe sobre os juizados especiais criminais.", "A suspensão ou a proibição de se obter a permissão ou a habilitação para dirigir veículo automotor pode ser imposta como penalidade principal, mas sempre de forma isolada, sendo vedada a aplicação cumulativa com outras penalidades.", "A penalidade de suspensão ou de proibição de se obter a permissão ou a habilitação para dirigir veículo automotor tem a duração de dois anos.", "Transitada em julgado a sentença condenatória, o réu será intimado a entregar à autoridade judiciária, em 24 horas, a permissão para dirigir ou a CNH.", "Ao condutor de veículo, nos casos de acidentes de trânsito de que resulte vítima, não se imporá a prisão em flagrante, nem se exigirá fiança, se ele prestar pronto e integral socorro àquela."], "E", "Quem presta pronto e integral socorro à vítima não é preso em flagrante nem paga fiança (CTB, art. 301). A erra: a Lei 9.099/1995 se aplica no que couber (art. 291). B erra: a suspensão ou proibição pode ser isolada ou cumulativa (art. 292). C erra: dura de 2 meses a 5 anos (art. 293). D erra: o prazo de entrega é de 48 horas (art. 293, § 1º).", ""],
  [71, 1, "con", "Família, segurança pública e meio ambiente", [], "Com relação às normas sobre segurança pública, meio ambiente e família, a CF dispõe que", ["a Polícia Federal, a PRF e a polícia ferroviária federal são consideradas, juntamente com as polícias militares e os corpos de bombeiros militares, forças auxiliares e reserva do Exército.", "o meio ambiente é bem de uso especial, que a administração pública pode utilizar para a realização de suas atividades e a consecução de seus fins.", "a PRF exerce as funções de polícia de fronteira e o policiamento ostensivo das rodovias federais.", "são penalmente inimputáveis apenas menores de dezesseis anos, sujeitos às normas da legislação especial.", "a comunidade formada por qualquer dos pais e seus descendentes é considerada entidade familiar."], "E", "A comunidade formada por qualquer dos pais e seus descendentes é entidade familiar (CF, art. 226, § 4º). A erra: só as polícias militares e os corpos de bombeiros militares são forças auxiliares e reserva do Exército (art. 144, § 6º). B erra: o meio ambiente é bem de uso comum do povo (art. 225). C erra: a polícia de fronteiras é atribuição da Polícia Federal (art. 144, § 1º, III). D erra: são inimputáveis os menores de 18 anos (art. 228).", ""],
  [72, 1, "con", "Administração pública e servidores", [], "Quanto às normas constitucionais sobre a administração pública e seus servidores, julgue os itens a seguir.\n\nI É possível a percepção simultânea de proventos de aposentadoria com a remuneração de cargo em comissão declarado em lei de livre nomeação e exoneração.\n\nII A prática de atos de improbidade administrativa implica a perda dos direitos políticos, a indisponibilidade dos bens e o ressarcimento ao erário.\n\nIII O teto remuneratório, como limite máximo de remuneração no serviço público, alcança também os detentores de mandato eletivo nas esferas federal, estadual e municipal.\n\nIV O servidor público investido em mandato eletivo federal, estadual, distrital ou municipal será afastado do cargo, emprego ou função, sendo-lhe facultado optar pela sua remuneração de servidor.\n\nV Com a extinção do cargo público ou a declaração de sua desnecessidade, o servidor estável ocupante deste será aposentado, com remuneração proporcional ao tempo de serviço.\n\nEstão certos apenas os itens", ["I e II.", "I e III.", "II e IV.", "III e V.", "IV e V."], "B", "Estão certos só I e III. I: o art. 37, § 10, permite acumular aposentadoria com cargo em comissão. III: o teto do art. 37, XI, alcança os detentores de mandato eletivo. II erra: a improbidade leva à suspensão, não à perda, dos direitos políticos (art. 37, § 4º). IV erra: no mandato federal, estadual ou distrital, o servidor é afastado sem poder optar; a opção pela remuneração é do prefeito (e do vereador sem compatibilidade de horário) (art. 38). V erra: o estável fica em disponibilidade, com remuneração proporcional, não é aposentado (art. 41, § 3º).", ""],
  [73, 1, "penal", "Crimes contra a administração pública", [], "Acerca dos crimes contra a administração pública, do abuso de autoridade, do tráfico ilícito de entorpecentes e da competência, assinale a opção correta.", ["Compete à justiça estadual processar e julgar sujeito ativo de crime de uso de documento falso, praticado mediante a apresentação de documentação falsa a um PRF.", "A legislação em vigor acerca do tráfico ilícito de entorpecente possibilita ao condenado por tráfico ilícito de entorpecente, desde que seja réu primário, com bons antecedentes e que não se dedique às atividades criminosas nem integre organização criminosa, a redução de um sexto a dois terços de sua pena, bem como a conversão desta em penas restritivas de direitos, desde que cumpridos os mesmos requisitos exigidos para a redução da pena.", "Pratica crime contra a honra e não desacato o sujeito ativo que manda uma carta para a residência de um PRF, afirmando que este é o \"maior apropriador do dinheiro público\".", "Compete à justiça militar processar e julgar militar por crime de abuso de autoridade, desde que este tenha sido praticado em serviço.", "A corrupção é crime necessariamente bilateral, de forma que a configuração da corrupção passiva dependerá da existência do crime de corrupção ativa."], "C", "O desacato exige que a ofensa seja feita na presença do funcionário; ofensa mandada por carta configura crime contra a honra. A erra: o documento foi apresentado a órgão federal, o que leva o caso à Justiça Federal. B erra para 2008: a lei de drogas proibia a conversão da pena em restritivas de direitos. D erra: a Súmula 172 do STJ manda o abuso de autoridade praticado por militar para a justiça comum, mesmo em serviço. E erra: a corrupção passiva pode existir sem a ativa, e vice-versa.", "Depois da prova, o STF (HC 97.256/2010) e a Resolução 5/2012 do Senado afastaram a proibição de converter a pena do tráfico privilegiado (B). A Lei 13.491/2017 ampliou o conceito de crime militar (CPM, art. 9º, II), e a Lei 4.898/1965 foi substituída pela Lei 13.869/2019, o que pôs em discussão a Súmula 172 (D). Em 2015, a Súmula 546 do STJ fixou a competência pelo órgão a que o documento falso foi apresentado (A)."],
  [74, 1, "penal", "Crimes contra o patrimônio", [], "A respeito dos crimes contra o patrimônio, assinale a opção correta.", ["Considere a seguinte situação hipotética. Roberto tinha a intenção de praticar a subtração patrimonial não-violenta do automóvel de Geraldo. No entanto, durante a execução do crime, estando Roberto já dentro do veículo, Geraldo apareceu e foi correndo em direção ao veículo. Roberto, para assegurar a detenção do automóvel, ameaçou Geraldo gravemente, conseguindo, assim, cessar a ação da vítima e se evadir do local. Nessa situação, Roberto responderá pelos crimes de ameaça e furto, em concurso material.", "Considere a seguinte situação hipotética. Fernando, pretendendo roubar, com emprego de arma de fogo municiada, R$ 20.000,00 que Alexandre acabara de sacar em banco, abordou-o no caminho para casa. Alexandre, no entanto, reagiu, e Fernando o matou mediante o disparo de seis tiros, empreendendo fuga em seguida, sem consumar a subtração patrimonial. Nessa situação, Fernando responderá por crime de latrocínio tentado.", "Considere a seguinte situação hipotética. Renato, valendo-se de fraude eletrônica, conseguiu subtrair mais de R$ 3.000,00 da conta bancária de Ernane por meio do sistema de Internet banking da Caixa Econômica Federal. Nessa situação, Renato responderá por crime de estelionato.", "Uma das distinções entre o crime de concussão e o de extorsão é que, no primeiro tipo penal, o funcionário público deve exigir a indevida vantagem sem o uso de violência ou de grave ameaça, que são elementos do segundo tipo penal referido.", "No crime de extorsão mediante seqüestro, faz jus à delação premiada o co-autor que delatou os comparsas e indicou o local do cativeiro, ainda que reste comprovado que a vítima tenha sido liberada após configurada a expectativa de êxito da prática delituosa, isto é, após o recebimento do dinheiro exigido como preço do resgate."], "D", "Na concussão, o funcionário exige a vantagem sem violência ou grave ameaça; com elas, o crime é extorsão. A erra: a grave ameaça logo depois da subtração, para garantir a posse, faz roubo impróprio (CP, art. 157, § 1º). B erra: com a morte consumada, há latrocínio consumado, mesmo sem a subtração (Súmula 610 do STF). C erra: subtrair valores da conta por fraude eletrônica é furto mediante fraude, não estelionato. E erra: a delação no sequestro exige facilitar a libertação da vítima (art. 159, § 4º).", "Depois da prova, a Lei 14.155/2021 criou o § 4º-B do art. 155 do CP, com pena maior para o furto mediante fraude por dispositivo eletrônico ou informático (C)."],
  [75, 1, "proc", "Inquérito policial", [], "Julgue os itens subseqüentes, acerca do IP.\n\nI Haverá nulidade no IP se a autoridade policial obrigar o indiciado a participar da reconstituição do crime, em face do princípio nemo tenetur se detegere.\n\nII Pelo fato de o IP ser um procedimento administrativo de natureza inquisitorial, a autoridade policial tem discricionariedade para determinar todas as diligências que julgar necessárias ao esclarecimento dos fatos, pois a persecução concentra-se, durante o inquérito, na figura do delegado de polícia.\n\nIII Em todas as espécies de ação penal, o IP deve ser instaurado de ofício pela autoridade policial, isto é, independentemente de provocação, pois tem a característica da oficiosidade.\n\nIV A requisição do MP para instauração do IP tem a natureza de ordem, razão pela qual não pode ser descumprida pela autoridade policial, ainda que, no entender desta, seja descabida a investigação.\n\nV A autoridade policial poderá promover o arquivamento do IP, desde que comprovado cabalmente que o indiciado agiu acobertado por uma causa excludente da ilicitude ou da culpabilidade.\n\nEstão certos apenas os itens", ["I e II.", "I e III.", "II e IV.", "III e V.", "IV e V."], "C", "Estão certos só II e IV. II: no inquérito, procedimento inquisitorial, a autoridade policial escolhe as diligências (CPP, art. 14). IV: a requisição do MP é ordem e deve ser cumprida. I erra: o indiciado não é obrigado a participar da reconstituição, mas vício do inquérito, que é peça informativa, não gera nulidade. III erra: na ação pública condicionada e na privada, o inquérito depende de representação ou requerimento (art. 5º, §§ 4º e 5º). V erra: a autoridade policial não pode arquivar o inquérito (art. 17).", ""],
  [76, 1, "proc", "Prisão em flagrante", [], "Julgue os itens a seguir, relativos à prisão em flagrante.\n\nI A prisão em flagrante tem natureza administrativa, mas, uma vez mantida e homologado o auto de prisão em flagrante pelo juiz, ela assume natureza jurisdicional.\n\nII Ocorre o chamado quase-flagrante quando, tendo o agente concluído os atos de execução do crime e se posto em fuga, inicia-se ininterrupta perseguição, até que ocorra a prisão.\n\nIII Não há crime e, portanto, o agente não pode ser preso, quando a preparação do flagrante pela polícia torna impossível a consumação desse crime.\n\nIV Ocorre flagrante forjado quando o fato típico não foi praticado, sendo simulado pela autoridade policial com o objetivo direto de incriminar alguém. Nesse caso, há absoluta ilegalidade e o responsável pelo ato responderá penal e administrativamente pela própria conduta.\n\nV Flagrante retardado é aquele no qual a polícia tem a faculdade de retardar a prisão em flagrante, visando obter maiores informações a respeito da ação dos criminosos.\n\nA quantidade de itens certos é igual a", ["1.", "2.", "3.", "4.", "5."], "E", "Os cinco itens estão certos para a doutrina da época. I: a prisão começa administrativa e, homologada pelo juiz, passa a jurisdicional. II: quase-flagrante é a perseguição logo depois do crime (CPP, art. 302, III). III: flagrante preparado que torna impossível a consumação não é crime (Súmula 145 do STF). IV: no flagrante forjado o fato não existiu, e quem o forjou responde. V: o flagrante retardado (ação controlada) permite adiar a prisão para colher mais provas.", "Depois da prova, a Lei 12.403/2011 mudou o art. 310 do CPP: o juiz não “mantém” o flagrante; relaxa a prisão, converte em preventiva ou concede liberdade provisória (I). A ação controlada (V) hoje está na Lei 12.850/2013, que substituiu a Lei 9.034/1995, e também no art. 53 da Lei 11.343/2006."],
  [77, 1, "adm", "Improbidade administrativa", [], "Durante abordagem a um carro, um PRF, ao revistar o porta-malas do automóvel, verificou que mercadorias de comercialização proibida no território nacional haviam sido importadas pelo condutor e estavam sendo transportadas. O condutor informou que era desempregado e fizera viagem a país vizinho porque pretendia vender as mercadorias no DF e, ato contínuo, ofereceu ao PRF R$ 1.000,00 para que este possibilitasse a continuidade da viagem, livre de qualquer repressão. Diante dessa situação hipotética e levando em consideração os ditames da Lei de Improbidade Administrativa, assinale a opção correta.", ["Caso o PRF aceitasse a oferta do condutor, estaria configurada a prática de improbidade administrativa na modalidade dos atos que importam enriquecimento ilícito.", "Caso o PRF aceitasse a vantagem econômica oferecida, o condutor poderia responder criminalmente, mas não responderia por improbidade administrativa, já que é particular, ou seja, não ocupa função pública.", "Caso o PRF aceitasse a vantagem econômica oferecida, estaria sujeito às cominações previstas na lei em questão, as quais impedem, para evitar a dupla penalização, a aplicação de outras sanções civis e administrativas.", "Caso o PRF aceitasse a propina oferecida, qualquer pessoa que viesse a ter ciência do fato poderia representar à autoridade administrativa competente para a instauração de investigação destinada a apurar a prática do ato de improbidade. Caso a representação atendesse aos requisitos legais, a apuração dos fatos seria processada na forma do procedimento previsto no CPC.", "No caso de o PRF praticar o ato ímprobo, qualquer ação destinada a aplicar sanções previstas na lei em apreço poderia ser proposta até cinco anos após o término do exercício do mandato do PRF."], "A", "Receber vantagem para tolerar atividade ilícita é ato que importa enriquecimento ilícito (Lei 8.429/1992, art. 9º). B erra: a lei alcança o particular que induz, concorre ou se beneficia do ato (art. 3º). C erra: as sanções da lei se somam às penais, civis e administrativas (art. 12). D erra: a apuração segue o processo disciplinar do servidor, não o procedimento do CPC (art. 14, § 3º). E erra: o PRF ocupa cargo efetivo, não mandato; o prazo era o da falta disciplinar punível com demissão (art. 23, II).", "Depois da prova, a Lei 14.230/2021 passou a exigir dolo para todo ato de improbidade e mudou a prescrição: 8 anos, contados do fato (art. 23)."],
  [78, 1, "carreira", "Lei 9.654/1998", [], "Acerca das previsões da Lei n.º 9.654/1998, que cria a carreira de PRF, assinale a opção correta.", ["O ocupante do cargo de PRF permanecerá no local de sua primeira lotação por um período mínimo de dois anos, exercendo atividades de natureza estritamente operacional voltadas ao patrulhamento ostensivo e à fiscalização de trânsito compatíveis com a sua experiência e aptidões.", "Os ocupantes de cargos da carreira de PRF não estão sujeitos à dedicação exclusiva às atividades do cargo, o que torna possível a cumulação do cargo com outra atividade privada.", "A carreira de que trata a Lei n.º 9.654/1998 é composta do cargo de PRF, estruturada nas classes de inspetor, agente e escrivão.", "A implantação da carreira de PRF ocorreu mediante transformação de milhares de cargos efetivos de patrulheiro rodoviário federal, do quadro geral do Ministério da Justiça, em cargos de PRF.", "O regime de trabalho dos PRFs é de 44 horas semanais."], "D", "A carreira foi implantada pela transformação de 10.098 cargos efetivos de patrulheiro rodoviário federal, do Ministério da Justiça, em cargos de PRF. A erra: o período mínimo na primeira lotação é de três anos. B erra: o cargo exige dedicação integral e exclusiva. C erra: escrivão não faz parte da carreira de PRF. E erra: a jornada é de 40 horas semanais.", ""],
  [79, 1, "adm", "Bens públicos", [], "Considerando que a União seja proprietária de um prédio no qual esteja instalada a PRF, assinale a opção correta a respeito desse bem, conforme o Código Civil.", ["Trata-se de um bem público de uso comum, haja vista que é acessível aos que necessitarem dos serviços lá prestados.", "Trata-se de bem particular, tendo em vista que é utilizado pela PRF.", "Consiste em bem de uso especial, e sua alienação será vedada enquanto ele conservar tal qualidade.", "Por ser bem dominical, é possível a sua alienação por notório interesse público.", "Por se encontrar sob a utilização da PRF, o bem não pode ser considerado de uso especial, dominical ou de uso comum do povo, enquadrando-se em categoria diversa daquelas previstas no Código Civil."], "C", "Prédio onde funciona serviço da administração é bem de uso especial (CC, art. 99, II), inalienável enquanto mantiver essa qualificação (art. 100). Não é bem de uso comum (A), nem particular (B), nem dominical (D), e o Código Civil não tem uma quarta categoria (E).", ""],
  [80, 1, "civil", "Responsabilidade civil", [], "Com referência à responsabilidade civil nos termos estabelecidos no Código Civil, cada uma das opções abaixo apresenta uma situação hipotética, seguida de uma assertiva a ser julgada. Assinale a opção que apresenta assertiva correta.", ["Felipe, menor de quatorze anos de idade, acidentalmente, quebrou o pára-brisa do carro de um vizinho com uma bola. Nessa situação, caberá ao pai de Felipe arcar com o prejuízo.", "Andréa, que, embora seja casada com Joaquim, é detentora de patrimônio próprio, causou danos a terceiro em razão de conduta culposa. Nessa situação, Joaquim deverá pagar pelos prejuízos causados por Andréa, apesar de ela ter patrimônio próprio.", "Antônio é motorista particular de Pedro e, nessa condição, causou danos a terceiro. Nessa situação, Pedro deverá arcar com a reparação dos danos causados por Antônio, sem qualquer possibilidade de cobrar deste a restituição dos valores pagos.", "Valéria é doente mental e foi interditada judicialmente, tendo-lhe sido nomeado curador que não é seu parente. Nessa situação, o curador nomeado estará isento de responder pelos prejuízos decorrentes da conduta de Valéria, por não ser seu parente.", "João tem dezessete anos de idade e, por imprudência, bateu sua bicicleta na porta de vidro de um escritório. Nessa situação, João responderá pessoal e exclusivamente pela reparação, já que, legalmente, ele é apenas relativamente incapaz."], "A", "Os pais respondem pelos filhos menores sob sua autoridade e em sua companhia (CC, art. 932, I), mesmo sem culpa própria (art. 933). B erra: não há essa responsabilidade do cônjuge. C erra: quem paga pode cobrar do causador do dano (art. 934). D erra: o curador responde pelo curatelado, seja ou não parente (art. 932, II). E erra: o menor de 17 anos não responde sozinho; os pais respondem, e ele só de forma subsidiária (art. 928).", ""],
];
